(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-mixed-resolution-serve"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-1\">一 · 一次混跑事故：统一分辨率假设如何击穿 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-2\">二 · 算法要解决的具体问题：请求内空间异构预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-3\">三 · 它不解决什么：边界要划清楚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-4\">四 · 适用边界的量化判断：patch 尺寸与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-5\">五 · 一个可复算的例子：缩略图与海报同批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-6\">六 · 工程判断：什么时候值得引入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-7\">七 · 边界先于收益：一次混跑事故暴露的调度失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-8\">八 · 当统一高分辨率把混合负载拖进双输区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-9\">九 · 请求解析与 patch 切分：预算标注发生在任何 GPU 工作之前</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-10\">十 · 同质 batch 聚合：按分辨率与步数分桶，而不是按请求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-11\">十一 · DiT 前向：桶内同构、桶间异构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-12\">十二 · 拼回 latent 与 VAE 解码：接缝是这一步的固有成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-13\">十三 · 超时降级与元数据膨胀：调度器的 CPU 侧账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-14\">十四 · 预算分配、拼接与调度器瓶颈：这套方案的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-15\">十五 · 预算公式的逐项拆解与量纲校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-16\">十六 · 从预算到分辨率档：离散化与对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-17\">十七 · 同质 batch 聚合的代价模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-18\">十八 · 复杂度估计的推导与失准传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-19\">十九 · 超时降级与拼接后处理的联合伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-20\">二十 · 预算公式的失效边界与调度器代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-21\">二十一 · 请求形态：什么样的负载才配得上 patch 级异构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-22\">二十二 · 预算分配对负载分布的敏感性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-23\">二十三 · 批大小与同质组的聚合效率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-24\">二十四 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-25\">二十五 · 配方参数的工程取值与验证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-26\">二十六 · 负载配方与失效边界：这套调度在什么请求形态下才划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-27\">二十七 · 硬件档位：按显存与 patch 并发量选卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-28\">二十八 · 并行拓扑：patch 组内张量并行、组间流式并发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-29\">二十九 · 量化方案：精度档位与 patch 复杂度对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-30\">三十 · KV 策略：patch 元数据与中间态的驻留规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-31\">三十一 · 调度参数：预算上下界、聚合键与降级阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-32\">三十二 · 可复现的配置思路：从档位表到上线检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-33\">三十三 · 部署配方：从显存档位到降级阈值的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-34\">三十四 · 显存：同质 batch 的对齐开销与碎片化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-35\">三十五 · 带宽：拼接回写与 VAE 解码的二次搬运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-36\">三十六 · 通信：分离式部署下 patch 批的跨卡聚合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-37\">三十七 · 功耗：异构 batch 的能效曲线与降级策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-38\">三十八 · 尾延迟：降级路径的收敛性与接缝风险</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-39\">三十九 · 规模上限：三个崩点的先后次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-40\">四十 · 规模上去以后：元数据、拼接后处理与尾延迟先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-41\">四十一 · 精度类失败：接缝、色带与预算失准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-42\">四十二 · 显存类失败：OOM 与批内分辨率错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-43\">四十三 · 调度类失败：批抖动与路由不均</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-44\">四十四 · 尾延迟尖刺：从排队到降级的链路诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-45\">四十五 · 调度器瓶颈与元数据膨胀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-46\">四十六 · 监控指标与回滚策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-47\">四十七 · 失效边界：从接缝、预算失准到调度器侧瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-48\">四十八 · 决策表的坐标轴：先问三个问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-49\">四十九 · 与阶段级流水的对照：切分维度不同，代价位置不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-50\">五十 · 与 VAE 分块、块级跳步、特征缓存的对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-51\">五十一 · 预算公式在两族之间的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-52\">五十二 · 适用条件与规模上限的判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mixed-resolution-serve-sec-53\">五十三 · 边界与选型：什么时候该用 patch 级异构，什么时候退回同质批</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:511px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 510.7 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求解析后按目标分辨率与 SLO 切 patch，标注每 patch 的预算</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器按分辨率/步数把 patch 聚成同质 batch，送 DiT 前向</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">低复杂度 patch 走低分辨率或少步，高复杂度 patch 保留全预算</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">patch 结果按坐标拼回完整 latent，送 VAE 解码</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">队列按 SLO 优先级重排，超时 patch 降级处理</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-mixed-resolution-serve-sec-1\">一 · 一次混跑事故：统一分辨率假设如何击穿 SLO</h3>\n<p>某文生图服务在 B200 单机上同时承接两类流量：营销素材的 2048×2048 高分辨率请求，以及社交场景的 512×512 缩略图请求。上线初期按最直观的方式实现——所有请求进入同一队列，统一按最高分辨率分配显存与算力预算。事故出现在一次投放高峰：512 缩略图请求的 P99 从平时的秒级区间被拉到与高分辨率请求同量级，前端超时重试又进一步放大队列长度，最终低分辨率请求的 SLO 违约率飙升，而 GPU 的 SM 占用并未打满。问题不在单请求的算子效率，而在调度层的一个隐含假设：<strong>分辨率是请求的属性，却被当成了整机的属性</strong>。</p>\n<p>把这个假设的代价写成公式就很直白。设请求集合中第 $p$ 个 patch 的步时延为 $t_{\\text{step}}(r_p)$，则一次批的总代价与利用率分别为：</p>\n<div class=\"formula\">$$\\text{Cost}=\\sum_{p}N_{p}\\,t_{\\text{step}}(r_{p}),\\quad \\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$$</div>\n<p>当所有 patch 被强制取 $r_p=r_{\\max}$，低复杂度 patch 的 $N_p$ 与 $t_{\\text{step}}$ 都被高估，$\\text{Cost}$ 里混入了大量无效计算；同时这些 patch 在 batch 中占位，使真正需要全预算的高复杂度 patch 得不到足够的显存与算力份额，$\\text{Util}$ 与尾延迟同时恶化。事故的本质是：<strong>统一分辨率把异构负载的方差转嫁给了排队系统</strong>，而不是在计算层吸收掉。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-2\">二 · 算法要解决的具体问题：请求内空间异构预算</h3>\n<p>混合分辨率补丁调度（mixed-resolution patch scheduling）针对的正是上述方差。它在去噪开始之前就把一张图切成 patch，按内容复杂度与请求 SLO 给每个 patch 标注分辨率与步数预算，再让调度器把同分辨率、同步数的 patch 聚成同质 batch 送进 DiT 前向。低复杂度 patch（大面积天空、纯色背景）走低分辨率或少步，高复杂度 patch（人脸、文字、细密纹理）保留全预算。这与按管线阶段切分的阶段级流水、只在解码期切块的 VAE 分块并行是三个不同层面的东西：本方法在去噪前就完成了请求内的空间异构分配，属于<strong>请求内空间异构调度</strong>。</p>\n<p>预算分配的判据由可用 SLO 余量决定，写成如下形式：</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>其中 $c_p$ 是内容复杂度，$t_{\\mathrm{wait}}$ 是排队时间，$t_{\\mathrm{unit}}$ 是单位步时延。这个式子的工程含义是：排队越久，可用于计算的预算越紧，复杂度高的 patch 优先保住预算，复杂度低的 patch 被压到 $r_{\\min}$。它把 SLO 从“事后监控指标”变成了“事前分配参数”，这是该算法区别于普通动态批处理的关键。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-3\">三 · 它不解决什么：边界要划清楚</h3>\n<p>第一，它不解决单请求内部的算力瓶颈。如果一个 2048×2048 请求的所有 patch 都是高复杂度（密集文字海报、复杂人脸群像），patch 级异构没有可压缩的空间，收益趋近于零，此时该看的是 NVFP4/FP8 量化、tcgen05 与 2-SM MMA 这类算子层手段，以及 KV/激活显存布局。第二，它不替代解码期的优化。VAE 解码按 tile 并行是另一条路径，patch 调度只保证送进 VAE 的 latent 已按坐标拼好，拼接处的接缝后处理反而会增加解码开销。第三，它不解决跨节点通信问题——NVLink 5 与 NCCL/NIXL 的拓扑效率、分离式预填/解码的配比，都不在它的作用域内。</p>\n<p>第四，也是最容易被忽略的一条：它不保证画质无损。patch 拼接处若重叠不足或融合权重设计不当，会出现可见接缝与色带；后处理开销一旦超过异构带来的吞吐收益，整体就是负优化。第五，复杂度估计偏差是它的固有失效模式——低复杂度 patch 预算给高了浪费算力，高复杂度 patch 预算给低了直接掉画质，两头都伤 SLO。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-4\">四 · 适用边界的量化判断：patch 尺寸与规模上限</h3>\n<p>适用性由两个尺度决定。patch 过小，调度器要维护的元数据条数与拼接后处理面积同步上升，CPU 侧调度开销和 GPU 侧拼接开销会吃掉异构收益；patch 过大，同质 batch 内的分辨率差异被抹平，异构收益收窄。工程上的判断标准是：<strong>单个 patch 的 DiT 前向时延应显著大于其调度与拼接的边际开销</strong>，否则切分本身不划算。</p>\n<p>规模上限受两条约束。其一是调度器元数据容量与优先级队列深度——高并发下 patch 元数据膨胀，调度器会成为 CPU 侧瓶颈，此时 GPU 反而等米下锅。其二是拼接后处理算力，重叠区域的重加权融合是逐像素操作，面积随 patch 数量线性增长。适用负载画像也因此清晰：高低分辨率混合、内容复杂度差异大的服务最受益；单一分辨率、内容复杂度均匀的负载不应引入这套机制。可用事实给出的吞吐锚点是混合负载下 1.4–1.8 倍提升，这个区间的下沿对应复杂度差异较小的负载，上沿对应分辨率跨度大且 SLO 分级明确的负载。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-5\">五 · 一个可复算的例子：缩略图与海报同批</h3>\n<p>设一批请求含 8 张 512×512 缩略图与 2 张 2048×2048 海报，按 256 像素网格切 patch：缩略图各 4 个 patch，海报各 64 个 patch，共 160 个 patch。统一分辨率方案下，全部 patch 按海报预算执行，缩略图的 32 个 patch 中有大量纯色背景被无谓地推到高分辨率多步，它们占据 batch 槽位，把 2 张海报的 128 个 patch 挤到后续批次，海报的尾延迟被拉长，缩略图的 P99 也被拖到与海报同级。</p>\n<p>patch 调度方案下，缩略图的背景 patch 被压到 $r_{\\min}$ 与少步，与海报中同样低复杂度的天空 patch 聚成同质 batch；人脸与文字 patch 保留全预算，单独成组。GPU 在每个时间片都有同质工作可做，$\\text{Util}$ 上升，缩略图请求因为不再与海报争夺全预算槽位而快速返回。队列按 SLO 优先级重排，超时 patch 降级处理，尾延迟被压回业务分级允许的范围。代价是调度器要维护 160 条 patch 元数据与优先级，以及拼接时的重叠融合——这部分开销必须被 1.4–1.8 倍的吞吐收益覆盖，否则应退回统一分辨率方案。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-6\">六 · 工程判断：什么时候值得引入</h3>\n<p>引入门槛可以归纳为三条可检验的条件：流量中分辨率分布存在明显双峰或长尾；同一张图内部的内容复杂度方差足够大（存在可被降级的 patch）；业务侧能给出分级的 SLO 而不是单一硬指标。三条同时成立时，patch 级异构 batch 让 GPU 始终有活干，收益是结构性的；缺一条，收益就会被拼接后处理与调度开销侵蚀。部署上，patch 级 batch 需按分辨率对齐显存，量化可与 FP8/NVFP4 叠加，硬件档位按显存选卡——这些是后续部分的主题，此处只作为边界条件指出。真正决定成败的是复杂度估计器的准确度：它偏差一点，预算分配就失准一分，画质与 SLO 同时受损，而这类损伤在监控上往往表现为“画质投诉”而非“延迟告警”，排查路径完全不同。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-7\">七 · 边界先于收益：一次混跑事故暴露的调度失配</h3>\n<p>某文生图服务把 1024×1024 商拍图与 512×512 社媒缩略图放进同一队列，调度器按队列内最高分辨率统一预留显存与算力：每个请求都按 1024² 的 latent 尺寸切 patch、按满步数排 batch。结果不是慢一点，而是双输——低分辨率请求被迫陪跑高分辨率的时间步预算，排队时间被拉长到超出其 SLO；同时高分辨率请求的 batch 里混进了大量本可低成本完成的 patch，GPU 的 FLOPs 有效利用率被拉低。用本卷的统一代价式看，问题一目了然：</p>\n<div class=\"formula\">$$\\text{Cost}=\\sum_{p}N_{p}\\,t_{\\text{step}}(r_{p}),\\quad \\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$$</div>\n<p>当所有 patch 被强制取 $r_p=r_{\\max}$ 时，$t_{\\text{step}}$ 对每个 patch 都取最大值，而低复杂度 patch 的真实 $\\text{FLOPs}_p$ 远小于分配值，分母 $T_{\\text{wall}}$ 被高分辨率步进撑满、分子却被浪费，Util 与尾延迟同时恶化。这正是混合分辨率补丁调度要解决的具体推理问题：<strong>请求内空间异构</strong>——同一张图里天空、纯色背景、皮肤平滑区与纹理密集区对分辨率与步数的需求本就不同，跨请求的高低分辨率混跑又把这种差异放大成调度层面的失配。它不解决的问题同样明确：它不做阶段级流水切分（那是管线并行的主题），也不等于 VAE 解码期的分块（后者只切解码），更不负责模型权重的精度选择——FP8/NVFP4 量化是另一条正交路径，可叠加但不替代 patch 预算分配。</p>\n<p>失效条件集中在三处。其一是拼接：patch 结果按坐标拼回完整 latent 再送 VAE 解码，若重叠区不足或融合权重设计不当，接缝处出现可见色带，后处理开销反噬吞吐收益——这是本方案最典型的“收益被自己吃掉”的失败模式。其二是复杂度估计偏差：$c_p$ 估高会让低复杂度 patch 白烧预算，估低则让高复杂度 patch 丢细节，画质与 SLO 同时受损，而 $c_p$ 本身只能来自轻量代理特征，不是真值。其三是调度器自身：patch 元数据与优先级队列在高并发下膨胀，CPU 侧成为瓶颈，GPU 反而等活。规模边界因此是双向的——patch 过小，调度与拼接开销压过异构收益；patch 过大，同质 batch 内差异收窄，1.4–1.8 倍的混合负载吞吐增益随之消退。适用面只落在“高低分辨率混合、内容复杂度差异大”的服务上；单一分辨率、内容均匀的负载切 patch 只是徒增元数据。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>本方案有效</th><th>本方案失效或收窄</th></tr></thead><tbody><tr><td>请求分辨率分布</td><td>高低分辨率混跑，SLO 分级</td><td>单一分辨率，统一预算已足够</td></tr><tr><td>内容复杂度</td><td>同图内平坦区与纹理区差异大</td><td>内容均匀，异构预算无收益</td></tr><tr><td>patch 粒度</td><td>中等粒度，拼接开销可控</td><td>过小则调度/拼接主导，过大则收益收窄</td></tr><tr><td>并发压力</td><td>元数据容量与 CPU 侧留有余量</td><td>优先级队列膨胀，调度器成瓶颈</td></tr></tbody></table>\n<p>工程判断上，先量三件事再决定是否启用：混合负载中低分辨率请求的排队时间占比、拼接后处理的单图开销、调度器元数据在峰值并发下的内存与 CPU 占用。若拼接开销已接近甚至超过异构节省的步进时间，或复杂度估计的偏差在业务画质验收中可见，就应退回统一分辨率路径，把精力放在连续批处理与显存管理上；反之，当高低分辨率请求确实共享同一 GPU 且 SLO 分级明确，patch 级异构 batch 才是把 Util 从“被最高分辨率钉死”中解放出来的手段。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-8\">八 · 当统一高分辨率把混合负载拖进双输区</h3>\n<p>线上事故的典型形态是这样：一个文生图服务同时承接 1024² 商拍主图与 512² 草稿预览两类请求，调度层为省事按最高分辨率统一预留显存与步数预算。结果低分辨率请求被迫排在高分辨率请求之后，且每步都按全画布算力执行，队列里 512² 请求的 P99 尾延迟被拉长到与 1024² 同级；同时高分辨率请求因显存被低分辨率请求的“虚高预留”挤占而频繁换入换出，GPU 利用率与 SLO 同时失守。这不是容量不足，而是预算分配粒度错了——问题出在“请求级统一分辨率”这一层抽象上，而非算力总量。用公式刻画即 <span class=\"formula\">$$\\text{Cost}=\\sum_{p}N_{p}\\,t_{\\text{step}}(r_{p}),\\quad \\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$$</span> 当所有 $r_p$ 被强制取 $r_{\\max}$ 时，$\\text{FLOPs}_p$ 对低复杂度 patch 严重高估，Util 被无效计算稀释，而 $T_{\\text{wall}}$ 由最慢请求决定，尾延迟无从压缩。</p>\n<p>本方案要解的正是这个“请求内空间异构”问题：请求解析后按目标分辨率与 SLO 切 patch 并标注预算，调度器按分辨率/步数把 patch 聚成同质 batch 送 DiT 前向，低复杂度 patch 走低分辨率或少步，高复杂度 patch 保留全预算，最后按坐标拼回 latent 送 VAE 解码。预算分配的核心式子是 <span class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</span> 它把排队时间 $t_{\\mathrm{wait}}$ 与内容复杂度 $c_p$ 直接折算成 patch 级分辨率/步数，超时 patch 由优先级队列降级处理。代价同样明确：patch 拼接处需重叠与后处理，VAE 解码开销上升；调度器要维护 patch 元数据与优先级，高并发下元数据膨胀会把瓶颈从 GPU 推到 CPU 侧。</p>\n<p>边界必须讲清。它适合高低分辨率混合、内容复杂度差异大的服务，混合负载下吞吐提升 1.4–1.8 倍；patch 过小则调度与拼接开销吃掉收益，patch 过大则异构收益收窄，规模上限受调度器元数据容量与拼接后处理算力约束。它不解决单请求内部无复杂度差异的场景——此时切 patch 只增加接缝风险；也不解决显存容量本身的硬约束，量化可叠加 FP8/NVFP4 但那是另一层手段。两类失效要盯住：拼接重叠不足或权重设计不当会出现可见接缝与色带，后处理开销抵消吞吐收益；复杂度估计偏差会让低复杂度 patch 预算过高或高复杂度 patch 预算过低，画质与 SLO 同时受损。区别于阶段级流水与仅解码期切块的 VAE 分块，本方法在去噪前就分配异构预算，因此复杂度估计器的准确性是整条链路的前置条件。</p>\n<h3 id=\"alg-mixed-resolution-serve-sec-9\">九 · 请求解析与 patch 切分：预算标注发生在任何 GPU 工作之前</h3>\n<p>混合分辨率补丁调度的第一步不在 GPU 上，而在请求入口。一个批里同时进来 1024×1024 与 512×512 的文生图请求时，调度器先做的是把每条请求的目标分辨率与 SLO 等级读出，再按固定 patch 网格（例如 64×64 latent 单元）把画布切开，为每个 patch 生成一条元数据记录：所属请求 ID、坐标 (i,j)、内容复杂度估计 c_p、SLO 截止时间、当前预算档位。这一步的输入是请求描述符与一张极低成本的复杂度图（可由上一批同位置 patch 的方差、或文本条件里空间 token 的注意力分布近似），输出是一张 patch 表，代价是纯 CPU 侧开销——每 patch 一条记录，千级 patch 的批在毫秒量级完成，但记录数与并发请求数相乘后就是调度器的内存与遍历成本。</p>\n<p>预算在这一步就被钉死，而不是等到进 GPU 才决定。核心公式是</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>其中 t_wait 是 patch 在队列里的已等待时间，t_unit 是单位步时延，c_p 是内容复杂度。这个式子的工程含义是：预算随剩余时间线性收缩，随复杂度线性放大，再被上下界夹住。一个 1024² 请求里天空区域的 patch 复杂度低，c_p 小，预算落到 r_min 档（低分辨率、少步）；人脸区域的 patch c_p 高，预算顶到 r_max。同一张图内部因此出现异构预算，这正是与阶段级流水、VAE 分块的本质区别——预算分配发生在去噪之前，而非管线切分或解码期切块。</p>\n<p>切分粒度本身是一笔账。patch 过小，元数据条数暴涨，调度器遍历与拼接后处理的算力吃掉异构收益；patch 过大，同质 batch 内的分辨率差异被抹平，异构收益收窄。工程上以 latent 网格的 1/8 到 1/4 边长为常见起点，使单请求 patch 数落在数十到数百之间，既让调度器有足够粒度做 SLO 重排，又不至于让 CPU 侧成为瓶颈。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-10\">十 · 同质 batch 聚合：按分辨率与步数分桶，而不是按请求</h3>\n<p>patch 表进入调度器后，聚合键不是请求 ID，而是（分辨率档, 步数档）二元组。调度器把当前所有待跑 patch 按这两个维度分桶，每个桶就是一个同质 batch，桶内 patch 共享同一套 DiT 前向配置——相同的 latent 空间尺寸、相同的 timestep 序列长度、相同的量化路径。这一步的输入是 patch 表与当前 GPU 上空闲的 SM 资源，输出是若干待发射的 batch 描述符，代价体现在两个方向：桶太碎则每桶 batch size 不足、MMA 利用率低；桶太少则同质 batch 内部被迫向上取齐，低预算 patch 被拉回高分辨率，异构收益归零。</p>\n<p>聚合的伪代码思路是：对每个桶按 SLO 截止时间排序，取前 N 个 patch 填满目标 batch size，N 由显存预算与分辨率档决定——高分辨率 patch 占的激活与 KV 更多，单桶 batch size 必须按分辨率对齐显存，否则一个 1024² 档的桶会把显存顶爆。这一步的吞吐代价直接对应公式里的 Util：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$$</div>\n<p>同质 batch 的意义就是让分母 T_wall 不被最慢的那个 patch 拖长。举例：一个批里 70% 是 512² 请求、30% 是 1024² 请求，若不聚合而统一按 1024² 跑，512² 的 patch 白算四倍面积，Util 掉到低位；聚合后 512² 桶以自身尺寸跑满 tensor core，1024² 桶独立成批，混合负载下吞吐提升 1.4–1.8 倍这个数字正是来自这种桶级并行，而不是来自单请求内的加速。</p>\n<p>聚合还承担 SLO 重排的职责：队列按 SLO 优先级重排，临近截止的 patch 优先入桶，哪怕它属于一个低优先级请求。这一步不产生 GPU 代价，但决定了后续降级逻辑的触发时机。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-11\">十一 · DiT 前向：桶内同构、桶间异构</h3>\n<p>发射阶段，每个桶独立走一遍 DiT 前向。输入是桶内 patch 的 latent 切片与对应 timestep，输出是该桶所有 patch 在若干步后的 latent 结果。低复杂度 patch 走低分辨率或少步——预算档位直接映射到 latent 的空间尺寸与去噪步数，高复杂度 patch 保留全预算。这里的关键机制是桶间异构、桶内同构：同一个 kernel 配置只服务一种分辨率与步数组合，避免在 kernel 内部做分支判断，也避免为迁就低分辨率 patch 而让高分辨率 patch 降档。</p>\n<p>代价分布在这一步最集中。高分辨率桶的每步时延随面积近似线性增长，低分辨率桶则面积小、步数少，单桶墙钟时间短。调度器的价值在于让这两类桶在时间轴上交错填充：当一个高分辨率桶在跑长步时，低分辨率桶可以在剩余 SM 上并行推进，GPU 始终有活干。显存侧，每个桶的激活占用按分辨率档独立核算，桶间不共享激活缓冲，因此显存峰值是各桶峰值之和而非最大值——这是 patch 级调度相对统一分辨率分配省显存的地方，但也是调度器必须精确核算、否则 OOM 的地方。量化可与 FP8/NVFP4 叠加，桶内统一量化路径，桶间可按分辨率档选不同精度，进一步拉开高低档的算力差距。</p>\n<p>一个具体例子：1024² 请求切成 256 个 patch，其中约四成被判为低复杂度，落入 r_min 档、步数减半。这四成 patch 的 FLOPs 降到全预算的几分之一，整请求的加权 FLOPs 显著低于统一全预算，而画质损失集中在纹理稀疏区域，人眼不敏感。这就是空间异构调度在单请求内部的收益来源。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-12\">十二 · 拼回 latent 与 VAE 解码：接缝是这一步的固有成本</h3>\n<p>各桶跑完后，patch 结果按坐标拼回完整 latent。输入是散落在各桶输出缓冲里的 patch latent，输出是一张完整的 latent 图，代价是拼接本身的内存搬运与坐标索引。真正昂贵的是接缝处理：patch 边界两侧由不同预算档位生成，分辨率与步数不一致会在边界产生可见接缝与色带，因此拼接时必须带重叠区，并在重叠区做加权融合，权重设计不当则接缝依旧可见。重叠区意味着额外 patch 被生成、额外 latent 被搬运，后处理开销直接抵消一部分吞吐收益。</p>\n<p>拼好的 latent 送 VAE 解码。解码按 tile 并行，tile 边界与 patch 边界不必对齐，但 tile 数随分辨率上升而增加，解码期的显存与带宽占用是整条链路里仅次于 DiT 前向的一段。工程判断是：patch 重叠比例与 VAE tile 大小要联合调，重叠太大则解码输入膨胀，重叠太小则接缝裸露；把重叠区控制在 patch 边长的固定比例、并让 VAE tile 覆盖整块重叠区，是让后处理开销可控的常见做法。</p>\n<p>这一步的失败模式很具体：重叠不足或融合权重设计不当，输出出现可见接缝与色带，业务侧不得不加后处理修补，修补算力把 1.4–1.8 倍的吞吐收益吃掉一部分。因此拼接与解码不是免费的收尾，而是必须计入容量规划的固定成本项。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-13\">十三 · 超时降级与元数据膨胀：调度器的 CPU 侧账本</h3>\n<p>链路末端是 SLO 兜底：队列按优先级重排后，若某 patch 的剩余时间已不足以跑完当前预算，调度器对其降级处理——砍步数或降分辨率档，把它塞进更低档的桶里赶在截止前出结果。输入是该 patch 的剩余预算与当前队列状态，输出是改写后的预算档位，代价是画质在超时 patch 上确定性下降，但尾延迟被保住。这是用画质换 SLO 的显式交易，业务可按请求等级决定降级阈值。</p>\n<p>调度器自身的账本在高并发下会膨胀：patch 元数据与优先级队列的条目数等于并发请求数乘以单请求 patch 数，千级并发、百级 patch 就是十万级记录，每次重排都要遍历。CPU 侧一旦成为瓶颈，GPU 就会出现空转等待桶描述符的间隙，Util 公式里的 T_wall 被拉长而 FLOPs 不变，利用率下滑。规模上限因此受调度器元数据容量与拼接后处理算力双重约束，而不是受 GPU 算力约束——这是本方法在容量规划上最容易被低估的一项。</p>\n<p>另一个失准来源是复杂度估计偏差：c_p 估高了，低复杂度 patch 拿到过高预算，白算；估低了，高复杂度 patch 预算不足，画质与 SLO 同时受损。复杂度图必须廉价且可在线更新，用上一批同位置 patch 的统计量做近似是常见折中，代价是跨批相关性弱时估计漂移。</p>\n<p>把五步串起来看，整条链路的代价结构是：入口切分与预算标注是 CPU 毫秒级开销，聚合是桶粒度与显存对齐的权衡，DiT 前向是算力与显存的主战场且桶间异构带来填充收益，拼接与 VAE 解码是接缝与 tile 并行的固定成本，降级与元数据是尾延迟与调度器容量的兜底账。每一步的输入输出都落在 patch 元数据这一条主线上，调度器的工程质量决定了异构收益能否兑现——桶划分粒度与重叠比例这两个参数，实际上就是这套方法在吞吐、画质、尾延迟三角上的两个旋钮。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-14\">十四 · 预算分配、拼接与调度器瓶颈：这套方案的失效边界</h3>\n<p>切完 patch 只是开始，真正的决策发生在预算标注这一步。每个 patch 的预算不是静态查表，而是随排队时间动态收缩的：<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>其中 $c_p$ 是内容复杂度估计，$t_{\\mathrm{wait}}$ 是 patch 在队列里的已等待时间。这个式子的工程含义是：等待越久，剩余可支配时延越少，预算被压向 $r_{\\min}$；复杂度越高，同样的时间片能换到的分辨率越高。失效点也在这里——$c_p$ 若被高估，低复杂度 patch 白白占用高预算，挤掉同 batch 内其他 patch 的算力；若被低估，高复杂度 patch 被压到少步低分辨率，画质塌陷且 SLO 仍不达标，两头受损。复杂度估计偏差是本方案最隐蔽的失败模式，因为它不会报错，只会表现为“画质莫名变差”或“尾延迟莫名超标”。</p>\n<p>拼接是第二道代价关口。patch 结果按坐标拼回完整 latent 再送 VAE 解码，边界处若重叠不足或融合权重设计不当，会出现可见接缝与色带；重叠区域越大，后处理与解码开销越高，吞吐收益被部分抵消。这里存在一个明确的规模边界：patch 过小，调度粒度细但元数据与拼接开销陡增；patch 过大，异构收益收窄，退化为接近统一分辨率的批处理。拼接后处理算力与调度器元数据容量共同构成规模上限，超过这个上限，1.4–1.8 倍的混合负载吞吐增益会被 CPU 侧调度与解码期后处理吃掉。</p>\n<p>第三道代价在调度器本身。patch 级 batch 需按分辨率对齐显存，队列按 SLO 优先级重排，超时 patch 降级处理——这些都要维护每 patch 的元数据、优先级与状态机。高并发下元数据与优先级队列膨胀，调度器成为 CPU 侧瓶颈，GPU 反而等调度。工程判断是：把同质 batch 的聚合放在 GPU 侧或固定形状的批处理队列里，元数据只保留分辨率档位、步数档位与 SLO 等级三个离散字段，避免逐 patch 细粒度记账；量化（FP8/NVFP4）可与本方案叠加，但 patch 级 batch 的显存对齐必须与量化后的 tile 形状一致，否则对齐开销会重新引入碎片。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>复杂度估计偏差</td><td>画质与尾延迟同时劣化</td><td>算力错配，SLO 双输</td></tr><tr><td>重叠不足/权重不当</td><td>接缝、色带</td><td>后处理与解码开销上升</td></tr><tr><td>元数据膨胀</td><td>调度器 CPU 饱和</td><td>GPU 空转，吞吐回落</td></tr></tbody></table>\n<h3 id=\"alg-mixed-resolution-serve-sec-15\">十五 · 预算公式的逐项拆解与量纲校验</h3>\n<p>核心公式是整条调度链路的“定价函数”，它把每个 patch 的算力预算写成 SLO 剩余时间与内容复杂度的乘积，再用上下界夹紧：</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>逐项看量纲：分子 $\\mathrm{SLO}-t_{\\mathrm{wait}}$ 是剩余时间预算，单位毫秒；分母 $t_{\\mathrm{unit}}$ 是单位步时延，单位毫秒每步；两者相除得到“还剩多少步”的无量纲步数额度。$c_p\\in(0,1]$ 是内容复杂度系数，对额度做缩放：平坦天空、纯色背景的 patch 取小值，纹理密集、边缘锐利的 patch 取接近 1 的值。于是括号内的量在物理意义上就是“这个 patch 最多能负担的步数”，$\\mathrm{clip}$ 把结果压进 $[r_{\\min},r_{\\max}]$，防止两类退化——剩余时间极少时预算被压到 0 导致 patch 完全不出图，剩余时间充裕时预算突破上限导致单个 patch 吃掉整卡时间片。</p>\n<p>关键一步在 $t_{\\mathrm{unit}}$ 的取法。它不是全局平均步时延，而是<b>按分辨率档位查表</b>：$t_{\\mathrm{unit}}(r)$ 随 latent 边长平方增长，因为 DiT 的注意力与 GEMM 计算量对 token 数近似二次与线性叠加。若用统一 $t_{\\mathrm{unit}}$，高分辨率档的 patch 会被系统性低估预算、低分辨率档被高估，异构收益立刻消失。工程上把 $t_{\\mathrm{unit}}$ 做成启动时标定的二维表（分辨率档 × 量化档），FP8 与 NVFP4 各有一份，因为 tcgen05 路径下不同精度的单位步时延差异直接改变预算分配结果。</p>\n<p>系统代价体现在这里：预算公式每调整一次 $r_{\\min}$，就改变一批 patch 的步数，进而改变同质 batch 的组成，最终改变 GPU 上活跃 warp 的数量。$r_{\\min}$ 设得过低，低复杂度 patch 被压成 1–2 步，画质崩坏；设得过高，低分辨率 batch 的步数拉长，SLO 尾延迟被拖。一个具体例子：某请求 SLO 为 900 ms，已排队 300 ms，$t_{\\mathrm{unit}}$ 在 1024 档为 6 ms/步，则步数额度为 100；某 patch $c_p=0.3$，得预算 30 步，被 $\\mathrm{clip}$ 到 $r_{\\max}=28$ 步；另一 patch $c_p=0.9$ 得 90 步，同样被压到 28 步——这说明 $r_{\\max}$ 是硬约束，复杂度差异只在额度不足时才真正体现为步数差异。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-16\">十六 · 从预算到分辨率档：离散化与对齐</h3>\n<p>预算算出的是连续步数，调度器需要把它映射成离散的分辨率档与步数档，才能聚成同质 batch。映射规则是：先按预算落区间选分辨率档 $r_p$，再在该档内取不超过预算的最大步数档。分辨率档通常取 2 的幂次边长（如 512/768/1024/1280），步数档取 4 的倍数，便于与 DiT 的采样器步进对齐。</p>\n<p>这一步引入一个容易被忽略的代价：<b>分辨率对齐的显存碎片</b>。同质 batch 要求 batch 内所有 patch 的 latent 张量形状一致，而 patch 在图像上的坐标不同，拼回时按坐标写入。若分辨率档不是 tile 尺寸的整数倍，拼接处需要重叠像素做羽化，重叠区在 VAE 解码时被重复计算。设重叠宽度为 $o$、patch 边长为 $s$，则有效计算膨胀率为 $(s+2o)^2/s^2$；$s=256$、$o=16$ 时膨胀约 1.27 倍，直接吃掉一部分吞吐收益。因此分辨率档的选取必须与 tile 尺寸、重叠宽度联合设计，而不是独立拍板。</p>\n<p>伪代码落到可实现层面，映射函数写成查表加钳位：</p>\n<ul>\n<li>输入：$\\mathrm{budget}_p$、分辨率档表 $R=[r_0,\\dots,r_k]$、每档步时延 $t_{\\mathrm{unit}}[r]$、步数档表 $S$。</li>\n<li>对每个候选档 $r$ 计算可负担步数 $\\lfloor \\mathrm{budget}_p \\cdot t_{\\mathrm{unit}}[r_{\\min}] / t_{\\mathrm{unit}}[r] \\rfloor$，取满足步数档下限的最大 $r$。</li>\n<li>输出 $(r_p, s_p)$，写入 patch 元数据；元数据字段至少含坐标、边长、分辨率档、步数档、SLO 截止时间、优先级。</li>\n</ul>\n<p>元数据是调度器的全部状态，它的容量决定规模上限。一个 4096×4096 的请求按 256 边长切 patch 得 256 个 patch，每个 patch 元数据按 64 字节计，单请求约 16 KB；并发 512 个请求时元数据约 8 MB，尚在 CPU 缓存可控范围。但若 patch 边长降到 64，patch 数暴增 16 倍，元数据与优先级队列的堆操作成为 CPU 侧瓶颈，调度器吞吐反而下降——这就是“patch 过小增加调度开销”的量化来源。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-17\">十七 · 同质 batch 聚合的代价模型</h3>\n<p>聚合的目标是让 GPU 上每个 batch 内的 patch 共享同一分辨率档与步数档，从而一次 DiT 前向服务多个 patch。设 batch 内 patch 数为 $B$，单 patch 单步 FLOPs 为 $f(r)$，则整批单步 FLOPs 为 $B\\cdot f(r)$；GPU 在峰值算力 $\\mathrm{peak}$ 下完成该步的时间下界为 $B\\cdot f(r)/\\mathrm{peak}$。实际墙钟时间 $T_{\\mathrm{wall}}$ 还要叠加 kernel 启动、TMEM 读写、权重加载等固定开销，因此小 batch 的效率损失显著：$B$ 从 1 增到 8 时固定开销被摊薄，$B$ 继续增大则收益趋缓，直到受限于 SM 占用与寄存器压力。</p>\n<p>利用率公式给出聚合质量的度量：</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$$</div>\n<p>分子是实际有效计算量，分母是峰值算力乘以墙钟时间。聚合不佳时，$T_{\\mathrm{wall}}$ 被固定开销与等待补全满，Util 掉到低位；聚合良好时 Util 逼近 1。注意分子只计有效 FLOPs，重叠区的重复计算不计入——这正好惩罚重叠过宽的设计，使 Util 成为重叠参数的调优信号。</p>\n<p>聚合的工程难点在<b>等待窗口</b>。调度器不能无限期等齐同档 patch，否则低并发时延恶化。做法是设一个微批次窗口 $W$（按毫秒计），窗口内凑够 $B_{\\min}$ 个同档 patch 即发车，凑不够则到窗口末尾强制发车，允许 batch 不满。$W$ 与 $B_{\\min}$ 的乘积关系决定吞吐与延迟的折中：$W$ 大则 batch 满、吞吐高但首 patch 等待长；$W$ 小则响应快但 Util 低。一个具体例子：1024 档 patch 的 $t_{\\mathrm{unit}}$ 为 6 ms，若 $W$ 设为 12 ms，则最多容忍两个步时延的等待，超过即发车，保证单个 patch 的排队延迟不超过其自身两步的计算时间。</p>\n<p>代价还体现在显存侧：同质 batch 的激活显存按 $B\\cdot s^2\\cdot d$ 增长（$d$ 为通道数），而不同分辨率档的 batch 不能共享同一块显存池，需按档位预分配或动态切分。显存池切分过细导致碎片，切分过粗导致高档 batch 挤占低档空间。工程判断是：档位数控制在 3–4 个，每档显存池按历史峰值利用率预留，剩余部分做弹性借用。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-18\">十八 · 复杂度估计的推导与失准传播</h3>\n<p>$c_p$ 不是凭空给的，它来自对 patch 内容的快速统计。可实现的估计器用 latent 的局部方差与梯度幅值构造：设 patch 内像素方差为 $\\sigma^2_p$、平均梯度幅值为 $g_p$，归一化后取</p>\n<div class=\"formula\">$$c_p=\\mathrm{clip}\\left(\\alpha\\cdot\\frac{\\sigma^2_p}{\\sigma^2_{\\mathrm{ref}}}+\\beta\\cdot\\frac{g_p}{g_{\\mathrm{ref}}},\\,c_{\\min},\\,1\\right)$$</div>\n<p>其中 $\\sigma^2_{\\mathrm{ref}},g_{\\mathrm{ref}}$ 是全图参考值，$\\alpha,\\beta$ 为权重。这一步的推导关键在“参考值取自同一请求”：跨请求归一化会让不同内容的请求之间预算不可比，而同请求归一化保证复杂度是相对量，高复杂度 patch 与低复杂度 patch 的预算差在请求内自洽。</p>\n<p>失准的传播路径值得单独讲。若 $c_p$ 被高估，该 patch 拿到超额步数，占用本应分给其他 patch 的 GPU 时间片，导致同批其他 patch 排队变长、SLO 逼近；若被低估，patch 步数不足，拼回后出现细节缺失，且由于预算公式的 $\\mathrm{clip}$ 下限，低估不会归零，只是画质降级。两种失准都同时损伤画质与 SLO，且失准在 batch 层面被放大：一个高估 patch 进入低分辨率 batch 会拉长该 batch 的步数档，整批延迟上升。</p>\n<p>缓解手段是<b>估计器与调度器解耦</b>：估计器只输出 $c_p$ 与置信区间，调度器在预算公式里对 $c_p$ 做保守化处理，取下界而非点估计。保守化使预算偏低，代价是画质略降但 SLO 更稳；对画质敏感的业务档则取上界。这就是“按业务分级”在公式层面的落点——分级不是给不同 SLO 数值，而是给 $c_p$ 的取法不同。</p>\n<p>系统代价：估计器本身要读 latent，一次全图扫描的带宽开销与一次 VAE 编码同量级。若在请求解析阶段做，等于在去噪前多付一次显存读；若复用编码器中间特征，则几乎零额外开销。工程上优先复用，估计器退化为对已有特征的池化统计。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-19\">十九 · 超时降级与拼接后处理的联合伪代码</h3>\n<p>降级逻辑必须与预算公式闭环：当 patch 的实际完成时间逼近 SLO 截止时间，调度器不再按原预算发车，而是把该 patch 的步数档下调一档或分辨率档下调一档，并把释放出的时间片让给同请求内尚未完成的 patch。判定条件是 $\\mathrm{SLO}-t_{\\mathrm{now}}&lt;t_{\\mathrm{unit}}(r_p)\\cdot s_p$，即剩余时间不够走完当前预算，触发降级。</p>\n<p>伪代码骨架如下，落在调度器主循环里：</p>\n<ul>\n<li>从优先级队列取 patch，按截止时间排序；对每个 patch 计算剩余时间与当前预算的可完成性。</li>\n<li>可完成则入对应 $(r,s)$ 的同质待发队列；不可完成则降级：先降步数档，仍不可完成再降分辨率档，降级后重算预算并回队。</li>\n<li>待发队列达到 $B_{\\min}$ 或窗口 $W$ 到期，发车一次 DiT 前向，结果写回 patch 结果缓冲。</li>\n<li>请求内所有 patch 完成后，按坐标拼回 latent，重叠区按距离加权羽化；拼回后的 latent 送 VAE 分块解码。</li>\n<li>拼接后处理的开销计入请求总时延，若后处理使总时延超 SLO，则回溯降低重叠宽度或减少 patch 数。</li>\n</ul>\n<p>这里的工程判断是：降级必须发生在发车前，而不是发车后中断。已发车的 batch 中途降级会破坏同质 batch 的一致性，迫使 kernel 重新配置，代价高于收益。因此降级判定的采样频率要与窗口 $W$ 对齐，每个窗口边界做一次全局重排。</p>\n<p>拼接后处理的代价可定性表述：重叠羽化是逐像素加权，计算量正比于重叠区面积乘以 patch 数，在 VAE 解码前执行，属于显存带宽受限操作而非算力受限。它与 VAE 分块解码的 tile 并行可以融合——羽化在 latent 域做，解码在像素域做，两者不冲突，但羽化后的 latent 需要一次完整的显存往返，这是拼接方案相对整图方案的固定额外开销。</p>\n<p>最后落在具体机制上：预算公式的 $\\mathrm{clip}$ 上下界、$t_{\\mathrm{unit}}$ 的分辨率查表、$c_p$ 的同请求归一化，三者共同决定 patch 级异构 batch 的组成；而窗口 $W$ 与 $B_{\\min}$ 决定这些 batch 能否被填满。吞吐提升 1.4–1.8 倍的来源不是单点优化，而是这三组参数在混合负载下同时避免了“按最高分辨率统一分配”的浪费与“batch 不满”的空转。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-20\">二十 · 预算公式的失效边界与调度器代价</h3>\n<p>核心预算公式 <span class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</span> 的推导关键一步在于把“剩余时间”折算成“可执行的步数上限”：分子 <span class=\"formula\">$\\mathrm{SLO}-t_{\\mathrm{wait}}$</span> 是 patch 从入队到交付的净时间窗，除以 <span class=\"formula\">$t_{\\mathrm{unit}}$</span> 得到该窗口内可容纳的单位步数，再乘内容复杂度 <span class=\"formula\">$c_p$</span> 把步数预算按纹理密度、边缘强度等指标缩放。clip 的上下界并非装饰：<span class=\"formula\">$r_{\\min}$</span> 防止低复杂度 patch 被压到无法拼回 latent 的退化分辨率，<span class=\"formula\">$r_{\\max}$</span> 防止高复杂度 patch 在宽裕窗口内吃掉整卡显存。失效条件很明确——当 <span class=\"formula\">$t_{\\mathrm{wait}}$</span> 逼近 SLO 时，括号内趋零并被 <span class=\"formula\">$r_{\\min}$</span> 截断，此时预算分配退化为“全部 patch 走最低档”，异构收益消失，系统等价于统一低分辨率跑，画质整体塌陷而非局部降级。</p>\n<p>复杂度估计偏差是第二个失效面。<span class=\"formula\">$c_p$</span> 若系统性高估，低复杂度 patch 拿到过高预算，同质 batch 内分辨率离散度上升，调度器被迫切出更多小 batch，<span class=\"formula\">$\\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$</span> 中的 <span class=\"formula\">$T_{\\text{wall}}$</span> 被 kernel 启动与显存对齐开销拉长；若低估，高复杂度 patch 预算不足，接缝与色带在拼回阶段暴露，后处理重叠与权重修正的解码开销反噬吞吐。工程上应把 <span class=\"formula\">$c_p$</span> 的估计误差纳入调度器的保守偏置，而非追求无偏估计。</p>\n<p>调度器本身是 CPU 侧瓶颈。每个 patch 需维护坐标、分辨率档位、步数预算、SLO 优先级与超时降级标记，高并发下元数据条目随批大小与切分数相乘膨胀；优先级队列每次重排都要跨请求比较，CPU 单核吞吐先于 GPU 饱和。规模上限由此确定：patch 过小则调度与拼接开销压过异构收益，patch 过大则同质 batch 内可聚合的 patch 数不足、收益收窄。一个可落地的判断是——把 patch 切分粒度绑定到显存对齐单位而非像素美学，让同分辨率 patch 组恰好填满一次 tcgen05 MMA 的 tile 形状，此时 1.4–1.8 倍吞吐区间才站得住；超出该粒度，调度器元数据容量与拼接后处理算力成为硬约束。</p>\n<h3 id=\"alg-mixed-resolution-serve-sec-21\">二十一 · 请求形态：什么样的负载才配得上 patch 级异构</h3>\n<p>混合分辨率补丁调度的收益不是无条件成立的，它本质上是用「调度与拼接的固定开销」去换「空间异构带来的算力节省」。因此负载配方第一条判断标准是：请求集合内部是否存在足够大的分辨率方差与内容复杂度方差。若一个服务实例里 90% 的请求都是同一档 1024×1024、内容复杂度接近（比如统一风格的电商白底图），切 patch 之后每个 patch 的预算几乎相同，同质 batch 与整图 batch 在 GPU 上等价，调度器却额外背上了元数据维护、坐标拼回、重叠后处理的成本，净收益为负。反过来，若同一批里既有 2048×2048 的海报生成、又有 512×512 的头像补图，且海报里大面积是纯色背景、头像里是高频纹理，那么按内容复杂度分配预算才有物理意义：背景 patch 走低分辨率少步，纹理 patch 保留全预算，同一张 GPU 上同时推进两类工作。</p>\n<p>长度分布在这里指的是「单请求的 patch 数量分布」而非文本 token 长度。patch 数量由目标分辨率与 patch 边长共同决定，分辨率档位越分散，单请求 patch 数的跨度越大。调度器把同分辨率、同步数预算的 patch 聚成同质 batch，因此真正决定批大小的是「每个同质组的 patch 池深度」。当请求到达率低、池子浅时，同质组凑不满一个高效 batch，GPU 要么空转要么被迫跨组混批，异构收益被稀释。工程上应把批大小理解为由池深度动态决定，而不是固定值：池深不足时宁可让调度器把相邻预算档（如 r=0.75 与 r=1.0）合并成一个稍宽的组，也不要把 batch 拆得过碎。</p>\n<p>并发维度上，patch 级调度适合中高并发、请求到达呈泊松或突发混合形态的服务。低并发（同时只有一两个请求在飞）时，单请求内部的 patch 已经能提供一定的并行度，但同质组数量少、组内深度浅，调度器的分组逻辑退化为「按 patch 顺序串行推进」，此时不如直接整图前向。高并发时元数据规模随在飞 patch 数线性增长，调度器 CPU 侧开销开始显性化——这正是失败模式里「高并发下元数据与优先级队列膨胀」的来源。可操作的判断是：在飞 patch 数达到调度器单核可维护的上限（取决于元数据结构体大小与每步重排频率）之前，收益随并发上升；越过后，CPU 成为瓶颈，GPU 反而等调度。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-22\">二十二 · 预算分配对负载分布的敏感性</h3>\n<p>预算公式把 SLO 剩余时间、排队时间与内容复杂度耦合在一起：</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>这个式子的行为强烈依赖负载的时间分布。当请求排队时间 $t_{\\mathrm{wait}}$ 在负载中占比很小（轻载、SLO 宽松），分子接近 SLO 本身，几乎所有 patch 都被 clip 到 $r_{\\max}$，异构退化——这解释了为什么轻载下 patch 调度看不到收益。当负载进入饱和区，$t_{\\mathrm{wait}}$ 抬升，分子收缩，低复杂度 patch 被压到 $r_{\\min}$，异构才真正展开；但若 $t_{\\mathrm{wait}}$ 继续上升逼近 SLO，所有 patch 都被压到 $r_{\\min}$，画质整体塌陷，此时系统已进入过载，调度策略应从「保画质」切换到「保尾延迟」的显式降级模式，而不是让公式被动地把预算压到底。</p>\n<p>内容复杂度 $c_p$ 的估计偏差是这条公式最脆弱的输入。若估计器把高频纹理 patch 误判为低复杂度，$c_p$ 偏小，预算被压低，该 patch 在拼回后表现为局部模糊或细节缺失，且因为它是「按预算正常完成」的，调度器不会触发任何降级补偿；反之把平坦背景误判为高复杂度，$c_p$ 偏大，预算虚高，这些 patch 挤占同质组的算力配额，把真正需要全预算的 patch 的排队时间推高，形成「劣币驱逐良币」的 SLO 侵蚀。工程上的防御是给 $c_p$ 估计加保守偏置（宁可高估复杂度），并在拼回后做一次轻量的局部一致性检查，把明显偏离邻域统计的 patch 标记为可疑、在下一轮迭代里补预算。</p>\n<p>代价层面，预算分配失准的后果不是均匀的画质下降，而是空间上不均匀的画质分布——同一张图里一部分区域锐利、一部分区域发糊，这种「画质马赛克」比整体降分辨率更难被业务接受。因此负载配方里必须包含一条：内容复杂度估计器的校准数据要覆盖该业务实际的内容分布，不能拿通用图像统计去套特定领域（比如线稿、医学影像、UI 截图），否则 $c_p$ 的系统性偏移会让预算公式整体失准。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-23\">二十三 · 批大小与同质组的聚合效率</h3>\n<p>同质 batch 的聚合效率可以用一个简单的比率刻画：有效 batch 填充率 = 实际参与前向的 patch 数 / 该组 batch 槽位容量。当请求形态是「少量大图 + 大量小图」时，大图贡献的 patch 数多、分辨率高，小图贡献的 patch 数少、分辨率低，两类 patch 天然落在不同预算档，同质组各自都能凑满，填充率高，这是最理想的负载配方。当请求形态是「大量中等分辨率、复杂度接近」时，所有 patch 挤进同一两个预算档，组数少但每组极深，调度器分组开销低、GPU 利用率高，但异构收益也低——这是「高吞吐但无画质分级」的形态，适合对画质一致性要求高、不需要按业务分级的场景。</p>\n<p>最差的形态是「分辨率连续分布、复杂度也连续分布」：patch 的预算值几乎两两不同，同质组被切得极碎，每组深度只有个位数，GPU 上频繁启动小 batch 前向，kernel launch 与 TMEM 分配的开销占比上升，实际吞吐反而低于整图批处理。这时调度器必须做预算量化——把连续的预算值离散到有限档位（例如分辨率 3 档 × 步数 2 档 = 6 个桶），用桶内最大预算作为组预算，牺牲少量画质换取组深度。量化档位数是负载配方的关键旋钮：档位太少则异构收益丢失，档位太多则组深度不足，工程上通常按「目标组深度 ≥ 单次前向的经济 batch 下限」反推档位数。</p>\n<p>显存侧的代价与批大小直接挂钩：同质组按该组分辨率对齐显存，高分辨率组的单 patch 激活与 KV 类中间张量占用远大于低分辨率组，因此调度器不能用一个全局 batch 上限，而要按组分别计算可容纳的 patch 数。若某高分辨率组因显存受限只能容纳很少 patch，该组会成为整个流水线的长尾，低分辨率组早早做完却在等它——这就是「按最高分辨率统一分配显存」的老问题在 patch 级调度里的残留形态，必须靠按组独立的显存配额来消解。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-24\">二十四 · 负载不对时的三种塌陷</h3>\n<p>第一种塌陷是「均质负载下的纯开销」。请求分辨率与复杂度高度一致时，patch 切分、元数据登记、坐标拼回、重叠区后处理全部照做，但没有任何 patch 走到低预算分支，异构收益为零，而拼接后处理的算力开销实打实增加，吞吐相对整图批处理下降。识别信号是同质组数量长期等于 1 或 2、且组内预算方差接近零，此时应自动关闭 patch 级调度、回退到整图路径。</p>\n<p>第二种塌陷是「拼接开销吃掉吞吐收益」。重叠不足或重叠区权重设计不当会在 patch 边界产生可见接缝与色带，业务方要求加后处理（羽化、频域融合、二次精修），后处理本身要跑一遍卷积类算子，其开销与 patch 数量成正比。当 patch 切得过小时，边界总长度随 patch 数增长，后处理开销可能抵消掉异构带来的 1.4–1.8 倍吞吐增益中的相当一部分。负载配方因此要约束 patch 边长下限：patch 越小，异构粒度越细但拼接税越重，存在一个由内容复杂度方差与后处理成本共同决定的最优边长，而不是越细越好。</p>\n<p>第三种塌陷是「调度器 CPU 瓶颈」。高并发下在飞 patch 数与优先级队列长度同时膨胀，每步前向之前都要重排队列、重算预算（因为 $t_{\\mathrm{wait}}$ 在变），调度器单核的每秒操作数成为系统上限。表现是 GPU 利用率曲线出现规律性凹口，凹口周期与调度重排周期一致。缓解手段包括：降低重排频率（每 N 步而非每步重算预算）、把预算计算下沉到 GPU 侧用轻量 kernel 做、对超时 patch 走预置的降级路径而不重新入队。这些手段都会牺牲一部分调度精度，属于负载配方里必须提前设定的降级阈值。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-25\">二十五 · 配方参数的工程取值与验证</h3>\n<p>把负载配方落成可部署的参数集，至少包含五项：patch 边长（决定拼接税与异构粒度）、预算离散档位数（决定组深度）、同质组最小深度（低于此值合并相邻档）、单组显存配额（按分辨率档分别设定）、调度重排周期（决定 CPU 开销与预算新鲜度）。这五项不是独立可调的——patch 边长变小会推高 patch 数，进而要求更大的元数据容量与更频繁的重排，而重排周期变短又加重 CPU 负担，形成一条耦合链。工程做法是先固定 patch 边长与档位数，再用实测的组深度分布去调最小深度与重排周期。</p>\n<p>验证负载是否「配得上」这套调度，最直接的办法是做一次 A/B：同一批真实请求分别走整图路径与 patch 路径，比较端到端吞吐、P99 尾延迟、以及拼回后图像在 patch 边界处的局部统计差异。若吞吐增益落在 1.4–1.8 倍区间之外（显著更低），说明负载方差不足或拼接税过重；若尾延迟没有改善甚至变差，说明优先级重排没有真正把超时 patch 提前，或降级路径没有被触发。这两个指标必须同时看：只盯吞吐会掩盖画质塌陷，只盯尾延迟会掩盖 CPU 瓶颈。</p>\n<p>最后一条工程判断落在容量规划上：patch 级调度的规模上限受调度器元数据容量与拼接后处理算力双重约束，而不是受 GPU 算力约束。扩容时若只加 GPU 不加调度侧资源，系统会在 GPU 尚未饱和时先撞上 CPU 墙。因此这套方法的部署配方里，调度器应作为独立可水平扩展的组件对待，其副本数与在飞 patch 数上限要和 GPU 池规模同步规划——这是负载配方从「算法可行」走到「服务可稳」的最后一步。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-26\">二十六 · 负载配方与失效边界：这套调度在什么请求形态下才划算</h3>\n<p>patch 级异构调度并非普适加速器，它的收益完全来自“同一批内分辨率与步数需求确实分层”。负载配方应满足三条：请求形态是混合分辨率的批量文生图（同一服务里同时有高分辨率精修与低分辨率快出）；内容复杂度在请求内与请求间都有明显方差（大面积平坦背景与密集纹理共存）；并发足够高，使同质 patch 组能聚成有意义的 batch，而不是每组只剩一两个 patch 却仍要付一次 DiT 前向的固定开销。批大小不该按请求数配，而应按同质 patch 组配——调度器的队列长度、每组 patch 数与显存对齐粒度共同决定有效批。预算分配由 <span class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</span> 给出，其中 $c_p$ 是内容复杂度估计、$t_{\\mathrm{wait}}$ 是排队时间；$c_p$ 一旦估偏，整条预算曲线就失准，这是本方案最脆弱的输入。</p>\n<p>负载不对时的失效是分层的。第一层是收益收窄：若请求分辨率高度同质，patch 分组退化为单一分辨率，异构 batch 与统一调度等价，却额外背上元数据与拼接开销；若 patch 切得过小，调度与拼接开销按 patch 数线性上涨，DiT 前向的固定成本被摊薄失败；切得过大则组内方差消失，1.4–1.8 倍的混合负载吞吐增益回落。第二层是画质事故：拼接处重叠不足或融合权重设计不当会出现可见接缝与色带，后处理开销吃掉吞吐收益；复杂度估计偏差使低复杂度 patch 预算过高（浪费算力、拖慢同组）或高复杂度 patch 预算过低（细节崩坏），画质与 SLO 同时受损。第三层是调度器自身成为瓶颈：高并发下 patch 元数据与优先级队列膨胀，CPU 侧排序与分组延迟进入关键路径，GPU 反而等队列。</p>\n<p>系统代价要按“每 patch 摊销”来算，而不是按请求算。设同质组 $g$ 的 patch 数为 $N_g$、组内步时 $t_{\\mathrm{step}}(r_g)$，则墙钟时间近似 <span class=\"formula\">$$\\text{Cost}=\\sum_{g}N_{g}\\,t_{\\mathrm{step}}(r_{g})+\\underbrace{T_{\\text{sched}}+T_{\\text{stitch}}}_{\\text{随 patch 数增长}}$$</span>，利用率 $\\text{Util}=\\sum_{p}\\text{FLOPs}_{p}/(\\text{peak}\\cdot T_{\\text{wall}})$ 里分子被降级 patch 削减、分母被调度与拼接抬高，两者反向拉扯。工程判断很直接：先测 $T_{\\text{sched}}$ 与 $T_{\\text{stitch}}$ 随 patch 数的斜率，再决定 patch 粒度下限；把 $c_p$ 估计器与预算公式解耦，允许按业务 SLO 分级校准；当同质组平均 patch 数低于 DiT 单次前向的经济批阈值时，退回请求级调度而非硬撑 patch 级异构。规模上限由元数据容量与拼接后处理算力共同封顶，越过这条线，吞吐增益会被 CPU 侧排队与 VAE 解码 tile 的额外开销抵消。</p>\n<h3 id=\"alg-mixed-resolution-serve-sec-27\">二十七 · 硬件档位：按显存与 patch 并发量选卡</h3>\n<p>patch 级调度把一次请求拆成若干同质 batch，意味着同一时刻 GPU 上驻留的激活与 KV 类中间态不再由单请求决定，而由“同时在跑多少个 patch 组”决定。选卡的第一约束因此不是单请求分辨率，而是显存能否容纳 <em>并发 patch 组数 × 每组激活</em> 加上 VAE 解码的 tile 缓冲。B200 与 B300 的差别在部署上体现为可承载的 patch 组上限：显存更大的一档可以把高分辨率 patch 组与低分辨率 patch 组同时驻留，减少组间切换的等待；显存紧张的一档则必须把高分辨率组串行化，异构收益被压缩。工程判断是：先按业务里最高分辨率请求的 patch 组激活量定单组显存，再用目标并发数乘上去，留出 VAE tile 并行与拼接后处理的余量，最后才看算力峰值。GB200/GB300 NVL72 机柜档位的价值不在单卡，而在于把 patch 组跨卡分布后仍能用 NVLink 5 做低延迟的 latent 汇聚——拼接发生在解码前，跨卡拼回完整 latent 的通信量随分辨率线性增长，这是机柜档位必须核算的带宽代价。</p>\n<p>量化方案与硬件档位耦合。FP8 与 NVFP4 的叠加能力决定了同一张卡能塞下多少个 patch 组：权重与激活降到低精度后，单组激活显存下降，并发组数上升，但低精度对 patch 边界处的数值一致性更敏感——拼接缝两侧若来自不同精度路径，色带风险上升。部署上应把量化档位与 patch 分组绑定：同质 batch 内部统一精度，跨组拼接时在 latent 空间做一次对齐归一化，而不是让不同精度的 patch 直接按坐标拼接。</p>\n<div class=\"formula\">$$\\text{Groups}_{\\max}=\\left\\lfloor\\frac{M_{\\text{free}}-M_{\\text{vae}}}{A_{\\text{group}}(r,\\text{prec})+M_{\\text{meta}}}\\right\\rfloor$$</div>\n<p>其中 $A_{\\text{group}}$ 是给定分辨率 $r$ 与精度档下单 patch 组的激活峰值，$M_{\\text{vae}}$ 是 VAE tile 并行缓冲，$M_{\\text{meta}}$ 是调度器元数据在显存侧的镜像。这个式子给出的是硬上限，实际配方要再乘一个安全系数，因为拼接后处理的临时张量与重叠区缓冲不在 $A_{\\text{group}}$ 里。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-28\">二十八 · 并行拓扑：patch 组内张量并行、组间流式并发</h3>\n<p>patch 级异构 batch 的并行拓扑有两层。组内是 DiT 前向的张量并行或 2-SM MMA 的切分，组间则是多个 patch 组在时间上交错占用 SM。若把组间也做成张量并行，低分辨率 patch 组会被高分辨率组的通信节奏拖住，异构收益消失。正确做法是组内固定并行度、组间用 CUDA 流做并发：高分辨率组占大块 SM，低分辨率组填剩余空隙，调度器按 SM 占用率而非请求数做准入。这与阶段级流水按管线切分不同，本方法的并行单位是 patch 组，拓扑随分辨率档位变化——高分辨率组可能需要跨卡张量并行，低分辨率组单卡即可，调度器要为两种拓扑维护不同的 launch 配置。</p>\n<p>代价落在通信与同步上。跨卡拼接时，各卡持有的 patch 结果需按坐标汇聚到负责 VAE 解码的卡，通信量正比于重叠区之外的边界像素数。NVLink 5 的高带宽让这一步在机柜内可接受，但跨节点就必须把拼接点前移，让同一请求的 patch 尽量落在同一 NVLink 域内。工程上用一个拓扑约束：请求解析时按 patch 坐标做亲和性分组，同域优先，跨域仅在低分辨率 patch 上允许。</p>\n<ul>\n<li>组内并行度按分辨率档位查表，不在运行时动态改。</li>\n<li>组间并发用流优先级表达 SLO：高优先级 patch 组占高优先级流。</li>\n<li>跨卡拼接点尽量落在同一 NVLink 域，减少 latent 汇聚的跳数。</li>\n</ul>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-29\">二十九 · 量化方案：精度档位与 patch 复杂度对齐</h3>\n<p>量化不是全局一刀切。patch 的复杂度估计 $c_p$ 已经在预算公式里出现，同一信号可以驱动精度选择：低复杂度 patch 走 NVFP4 甚至更低，高复杂度 patch 保留 FP8 或更高档，避免细节区在低精度下丢失高频。这与 DiT NVFP4 混合精度量化的全局分层不同，本方法的精度决策发生在 patch 粒度，且与分辨率预算同源——两者共用 $c_p$，减少一次额外估计。部署配方里应把精度档位写成 patch 元数据的一个字段，调度器按 (分辨率, 步数, 精度) 三元组聚合同质 batch，聚合键越多，batch 同质性越好但组数越碎，需要在组数与显存之间取平衡。</p>\n<p>代价是校准与数值一致性。patch 级 PTQ 校准若按全局统计量做，低复杂度 patch 的激活分布会被高复杂度 patch 拉偏，量化误差在拼接处放大。可行做法是按分辨率档位分别校准，校准集覆盖各档的典型内容，再把缩放因子固化进调度器的档位表。推理时的额外开销来自精度切换的 kernel 重载，因此同质 batch 内部不允许精度混用，切换只发生在组边界。</p>\n<div class=\"formula\">$$\\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}(r_{p},\\text{prec}_{p})}{\\text{peak}(\\text{prec})\\cdot T_{\\text{wall}}}$$</div>\n<p>注意分母的 peak 随精度档变化：NVFP4 的峰值吞吐高于 FP8，若把高复杂度 patch 强行降到 NVFP4，分子里的有效 FLOPs 不变但画质下降，Util 数字好看而 SLO 失守。配方应把 Util 按精度档分别统计，避免用混合精度的高峰值掩盖低档 patch 的实际占用。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-30\">三十 · KV 策略：patch 元数据与中间态的驻留规则</h3>\n<p>扩散去噪没有自回归 KV cache，但 patch 级调度有自己的“KV 等价物”：每个 patch 组的 latent 中间态、步数计数、重叠区缓冲与优先级标记。这些状态的驻留策略直接决定调度器能否在超时降级时快速重排。规则应是：活跃 patch 组的中间态常驻显存，等待队列中的 patch 只保留元数据不保留 latent，超时降级时按元数据重建低预算路径而不是从零重算。这样降级的代价是一次低分辨率前向，而不是整段重跑。</p>\n<p>显存代价来自重叠区。拼接缝需要重叠与后处理，重叠区的 latent 在拼接完成前必须保留，重叠比例越高，驻留显存越大、后处理算力越多。配方上把重叠比例与分辨率档位绑定：高分辨率 patch 用较小重叠比例配合更精细的权重，低分辨率 patch 用较大重叠比例换取简单后处理。这与 VAE 分块并行解码的 tile 缓冲是两笔账，不能混算。</p>\n<table class=\"mini\"><thead><tr><th>状态类别</th><th>驻留位置</th><th>降级行为</th><th>主要代价</th></tr></thead><tbody><tr><td>活跃组 latent</td><td>显存常驻</td><td>不降级，按预算跑完</td><td>占 $A_{\\text{group}}$ 峰值</td></tr><tr><td>等待队列元数据</td><td>主机内存 + 显存镜像</td><td>按 SLO 重排优先级</td><td>高并发下 CPU 侧膨胀</td></tr><tr><td>重叠区缓冲</td><td>显存，拼接后释放</td><td>降级时缩小重叠比例</td><td>后处理算力与显存</td></tr></tbody></table>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-31\">三十一 · 调度参数：预算上下界、聚合键与降级阈值</h3>\n<p>调度器暴露的参数不多，但每一个都直接对应公式里的量。$r_{\\min},r_{\\max}$ 是预算上下界，决定异构收益的天花板：$r_{\\min}$ 太低会让低复杂度 patch 的拼接开销占比上升，$r_{\\max}$ 太高则高复杂度 patch 独占 SM 时间过长。聚合键的选择决定 batch 同质性，三元组 (分辨率, 步数, 精度) 是最细的键，实际部署常退化为二元组以控制组数。降级阈值对应 $t_{\\text{wait}}$ 的上界，超时 patch 按元数据重建低预算路径，阈值应设为 SLO 减去一次低分辨率前向的时延，留出拼接与 VAE 解码的余量。</p>\n<p>伪代码思路：请求解析后对每个 patch 计算 $\\mathrm{budget}_p$，按聚合键入桶；调度循环每次取优先级最高的桶，检查显存准入，准入通过则 launch 同质 batch；批次完成后更新 $t_{\\text{wait}}$，对超阈值 patch 打降级标记并重算预算。关键工程点是准入检查必须包含重叠区缓冲，否则拼接阶段会因显存不足而回退，吞吐收益被抵消。</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>这个式子在本部分的角度是参数标定：$t_{\\text{unit}}$ 必须按目标硬件档位与精度档实测，不能跨档复用；$c_p$ 的估计偏差是已知失败模式，配方上应给 $c_p$ 加一个保守偏置，宁可高估复杂度也不让高细节 patch 掉预算。混合负载下吞吐提升 1.4–1.8 倍的前提是聚合键与准入参数调对，键太细则组数爆炸、调度开销吃掉收益，键太粗则异构退化为统一分辨率。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-32\">三十二 · 可复现的配置思路：从档位表到上线检查</h3>\n<p>把上述选择固化成一张档位表，是配方可复现的关键。表的三维是硬件档、分辨率档、精度档，每格填入并行度、聚合键、重叠比例、预算上下界与准入显存阈值。上线前按业务请求分布跑一遍离线回放，统计各档的组数与 $T_{\\text{wall}}$，验证 Util 与尾延迟同时达标；回放中若发现某档组数过高，就把该档的聚合键粗化一级，代价是同质性下降但调度开销回落。这套流程不依赖具体实验数字，只依赖档位表与回放脚本，换硬件档时重标 $t_{\\text{unit}}$ 即可。</p>\n<p>上线检查清单要覆盖已知失败模式：拼接缝的可见接缝与色带用重叠比例与权重设计兜底，后处理开销计入 $T_{\\text{wall}}$ 而不是藏在解码阶段；复杂度估计偏差用保守偏置与降级路径兜底；patch 元数据与优先级队列在高并发下膨胀，用主机内存分片与批量重排把 CPU 侧压力摊平。最后一条工程判断：patch 级调度的收益来自异构 batch 填满 SM，一旦调度器本身成为瓶颈，收益立刻反转，因此调度参数的上限应由调度器吞吐而非 GPU 峰值决定。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-33\">三十三 · 部署配方：从显存档位到降级阈值的闭环</h3>\n<p>把 patch 级异构调度落到可复现配置，先定三个不可协商的量：patch 元数据驻留显存、同质 batch 的对齐粒度、以及降级触发的余量。硬件档位按单卡显存选：显存紧的档位把 $r_{\\min}$ 压低、把 patch 尺寸取大以抑制元数据膨胀；显存宽的档位保留全预算 patch 并允许更高 $r_{\\max}$。量化与 patch 调度正交叠加——DiT 前向用 FP8 或 NVFP4 降权重量化带宽，但预算公式里的 $t_{\\mathrm{unit}}$ 必须按实际量化后的步时延重标定，否则 $\\mathrm{budget}_p$ 会系统性偏高。并行拓扑上，同质 batch 沿序列维切分做 TP 时，patch 边界必须与切分边界对齐，否则跨卡 all-reduce 会把拼接接缝放大成跨设备色差。</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>KV 策略在本方案里不是注意力缓存而是 latent 与 patch 元数据的驻留策略：同质 batch 的中间 latent 按 tile 常驻，跨 batch 复用的坐标索引放主机侧并以固定容量环形缓冲，容量上限直接决定调度器能否撑住高并发。调度参数取三档：批聚合窗口按分辨率桶分别设阈值，避免低分辨率 patch 被高分辨率桶长期饿死；超时降级阈值取 $\\mathrm{SLO}$ 的固定比例留作 VAE 拼接后处理的余量；重叠像素宽度与后处理权重作为独立可调项，重叠不足即出现可见接缝与色带，后处理开销会吃掉 1.4–1.8 倍吞吐收益的一部分。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>复杂度估计偏差</td><td>画质与 SLO 同时受损</td><td>按 patch 回采实际步时延校正 $c_p$</td></tr><tr><td>元数据与优先级队列膨胀</td><td>调度器成 CPU 侧瓶颈</td><td>环形缓冲限容、按桶淘汰</td></tr><tr><td>patch 过小</td><td>调度与拼接开销压过异构收益</td><td>设 patch 尺寸下限</td></tr></tbody></table>\n<p>边界判断落在两个比值上：patch 尺寸相对目标分辨率的占比决定异构收益是否被拼接开销吞没，元数据条目数相对调度器 CPU 核数的比值决定高并发下是否退化为串行。规模上限由拼接后处理算力与元数据容量共同封顶，超出即应回退到按请求整图分配，而不是继续缩小 patch。</p>\n<h3 id=\"alg-mixed-resolution-serve-sec-34\">三十四 · 显存：同质 batch 的对齐开销与碎片化</h3>\n<p>patch 级调度把“同分辨率、同步数”的 patch 聚成一个同质 batch，这一步在显存上并不是免费的。DiT 前向的激活张量形状由 batch 内 patch 的空间尺寸与通道数决定，同质 batch 意味着每个 batch 的 latent 张量必须按该组的分辨率对齐分配；不同分辨率组交替占用显存，若调度器不做预留与复用，显存分配器会在组切换时反复申请、释放大块激活缓冲，形成外部碎片。工程上的做法是给每个分辨率档位预分配固定大小的激活池（activation pool），组内 batch 从池中切片，组间切换只换指针不换物理页。代价体现在显存占用上：档位数越多，池的总量越大，因为每个档位都要按该档最大 batch 预留峰值激活。以三档（全分辨率、半分辨率、四分之一分辨率）为例，池容量近似为各档峰值之和，而非单一峰值，显存开销高于统一高分辨率跑法在低负载时的占用，但低于统一高分辨率在满批时的占用。</p>\n<p>更隐蔽的是 patch 元数据本身的显存与主机内存占用。每个 patch 需要记录坐标、分辨率档、步数预算、SLO 优先级、所属请求 ID，这些结构在高并发下按 patch 数量线性膨胀。设单请求切出 <span class=\"inline-math\">\\(N_p\\)</span> 个 patch，并发请求数为 <span class=\"inline-math\">\\(Q\\)</span>，元数据条目数为 <span class=\"inline-math\">\\(N_p Q\\)</span>；当 patch 切得细、并发拉高，元数据从 KB 级涨到 MB 级，且调度器每步都要遍历、排序，CPU 侧缓存命中率下降。这正是规模上去后第一个崩点：不是 GPU 算力不够，而是调度器的元数据表与优先级队列先饱和。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{act}}=\\sum_{g\\in\\text{groups}}\\;B_g\\cdot S_g\\cdot C\\cdot d,\\qquad \\text{Mem}_{\\text{meta}}=N_p\\,Q\\cdot s_{\\text{entry}}$$</div>\n<p>其中 <span class=\"inline-math\">\\(B_g\\)</span> 为组内 batch 大小，<span class=\"inline-math\">\\(S_g\\)</span> 为该组 patch 空间尺寸，<span class=\"inline-math\">\\(C\\)</span> 为通道数，<span class=\"inline-math\">\\(d\\)</span> 为激活字节数，<span class=\"inline-math\">\\(s_{\\text{entry}}\\)</span> 为单条元数据字节数。前者决定 GPU 显存墙，后者决定主机侧调度墙。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-35\">三十五 · 带宽：拼接回写与 VAE 解码的二次搬运</h3>\n<p>patch 结果按坐标拼回完整 latent，再送 VAE 解码，这一步的带宽代价常被低估。去噪阶段每个 patch 的输出要写回一张完整 latent 图的对应区域，写回是散射（scatter）而非连续拷贝：patch 在 latent 上按网格排布，写回时目标地址跨 stride 跳跃，HBM 上的写事务被打散，有效带宽低于连续写的峰值。若 patch 之间带重叠区（为压接缝），重叠像素被多次写入，写放大系数约为 <span class=\"inline-math\">\\(1+o/w\\)</span>，<span class=\"inline-math\">\\(o\\)</span> 为重叠宽度、<span class=\"inline-math\">\\(w\\)</span> 为 patch 宽度。重叠越宽接缝越少，但写回带宽与后续 VAE 解码的输入尺寸同步上升。</p>\n<p>VAE 解码按 tile 并行时，输入是拼好的完整 latent，tile 边界同样需要重叠上下文，解码器在每个 tile 上重复计算边界带。设 tile 数为 <span class=\"inline-math\">\\(T\\)</span>、重叠比例为 <span class=\"inline-math\">\\(\\rho\\)</span>，解码 FLOPs 放大约 <span class=\"inline-math\">\\(1+\\rho\\)</span>，同时 tile 间的特征图搬运走 L2 与 HBM，带宽压力集中在解码阶段而非去噪阶段。工程判断是：当 patch 切得较细、重叠比例较高时，解码期的带宽与算力放大可能吃掉去噪期异构调度省下的时间，吞吐收益从 1.4–1.8 倍区间向下滑。因此重叠宽度应作为可调参数与 patch 尺寸联合寻优，而不是固定值。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>带宽形态</th><th>放大来源</th><th>对尾延迟的影响</th></tr></thead><tbody><tr><td>patch 写回</td><td>散射写，跨 stride</td><td>重叠区重复写</td><td>与 patch 数成正比</td></tr><tr><td>VAE tile 解码</td><td>连续读 + 边界重复算</td><td>tile 重叠上下文</td><td>集中在解码末段</td></tr><tr><td>元数据遍历</td><td>主机内存读</td><td>条目数膨胀</td><td>每步调度固定开销</td></tr></tbody></table>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-36\">三十六 · 通信：分离式部署下 patch 批的跨卡聚合</h3>\n<p>当预填与解码分离、或 DiT 前向跨多卡张量并行时，同质 patch batch 的聚合引入新的通信面。调度器在 CPU 侧决定哪些 patch 进哪个 batch，但 patch 的 latent 数据可能分布在不同 GPU 的显存里——尤其是分离式架构中，请求解析与切 patch 发生在前端节点，去噪发生在推理节点。把同分辨率 patch 聚成 batch 需要跨节点搬运 latent 切片，走 NVLink 5 域内或 NIXL 跨节点传输。聚合的收益是 batch 变大、MMA 利用率上升；代价是每次组批一次 all-to-all 式的数据重排，通信量与 patch 字节数成正比，且组批越频繁、batch 越小，通信开销占比越高。</p>\n<p>设单 patch latent 字节数为 <span class=\"inline-math\">\\(b_p\\)</span>，一次组批搬运 <span class=\"inline-math\">\\(K\\)</span> 个 patch，链路有效带宽为 <span class=\"inline-math\">\\(W\\)</span>，则组批时延为 <span class=\"inline-math\">\\(K b_p/W\\)</span>。当 <span class=\"inline-math\">\\(K b_p/W\\)</span> 接近甚至超过该组单步计算时延时，异构组批就失去意义——省下的算力被通信吃掉。规模上去后第二个崩点出现在这里：并发请求跨节点分布越散，patch 聚合的通信半径越大，组批粒度被迫放大以摊薄通信，而大 batch 又拉长了单组完成时间，尾延迟恶化。可行的折中是按节点局部性组批，优先聚合同节点 patch，跨节点 patch 单独成组或降级为低分辨率快速路径。</p>\n<div class=\"formula\">$$t_{\\text{gather}}=\\frac{K\\,b_p}{W},\\qquad \\text{条件：}\\;t_{\\text{gather}}&lt;\\frac{B_g\\,t_{\\text{step}}(r_g)}{\\text{overlap}}$$</div>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-37\">三十七 · 功耗：异构 batch 的能效曲线与降级策略</h3>\n<p>patch 级异构调度的能效优势来自“让 GPU 始终有活干”，但功耗曲线并非线性。低分辨率、少步数的 patch 组在 SM 占用率低时，GPU 进入低频高能效区间；高分辨率全预算组把 SM 与 Tensor Core 拉满，功耗逼近板卡上限。混合负载下两组交替执行，GPU 频率在高低之间切换，DVFS 的响应滞后于组切换节奏，导致切换瞬间的能效损失。更关键的是，功耗墙（power cap）在机架级（GB200/GB300 NVL72）是共享资源：一个高分辨率组把功耗拉高，同机架其他推理实例被迫降频，跨请求的尾延迟被连带拖长。因此 patch 调度器在分配预算时不能只看单卡 SLO，还要看机架功耗预算的剩余量，把高预算 patch 组在时间上错峰排布。</p>\n<p>工程上的做法是给每个分辨率档位标注功耗权重，调度器按当前功耗余量决定是否把某组 patch 推迟一个调度周期，或把其分辨率预算下调一档。这与 SLO 降级是同一套机制的两个触发源：时间超时触发降级，功耗余量不足也触发降级。代价是降级判据变多，调度器的决策逻辑与元数据字段同步膨胀，进一步加重第三节提到的 CPU 侧瓶颈。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-38\">三十八 · 尾延迟：降级路径的收敛性与接缝风险</h3>\n<p>尾延迟是本方法的核心卖点，也是规模上去后最脆弱的一环。超时 patch 降级处理的逻辑是：队列按 SLO 优先级重排，临近截止的 patch 被抽出、降低分辨率或步数预算、快速跑完。问题在于降级后的 patch 与同图未降级的 patch 在画质上不一致，拼回时在降级 patch 边界出现分辨率断层，表现为局部模糊或纹理跳变，比单纯的接缝更难后处理。设降级 patch 集合为 <span class=\"inline-math\">\\(D\\)</span>，其边界像素数为 <span class=\"inline-math\">\\(|\\partial D|\\)</span>，后处理修复这些边界的开销与 <span class=\"inline-math\">\\(|\\partial D|\\)</span> 成正比；当降级 patch 分散而非连片时，边界周长最大化，修复成本最高。</p>\n<p>因此降级策略应尽量让降级 patch 连片——按空间邻接关系成组降级，而非按到达顺序零散降级。这要求调度器维护 patch 的空间邻接图，在超时判定时做邻域扩展，把相邻 patch 一并降级。代价是邻接图的维护与扩展查询增加调度开销，且连片降级会一次性拉低整块区域的画质，业务侧需按区域重要性配置降级白名单。规模上去后第三个崩点：并发越高、超时 patch 越多，邻域扩展的查询与后处理修复同时膨胀，尾延迟的收益被后处理时延抵消，SLO 达标率反而下降。</p>\n<div class=\"formula\">$$\\text{Cost}_{\\text{seam}}\\propto|\\partial D|,\\qquad |\\partial D|\\;\\text{最小化}\\;\\Leftarrow\\;\\text{连片降级}$$</div>\n<p>具体例子：一张 1024×1024 的 latent 切成 4×4 共 16 个 patch，若 5 个零散 patch 超时降级，边界像素数远大于把右下 2×2 连片 4 个 patch 降级的情形；后者虽画质损失集中，但接缝修复的后处理算力显著更低，尾延迟更可控。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-39\">三十九 · 规模上限：三个崩点的先后次序</h3>\n<p>把显存、带宽、通信、功耗、尾延迟放在同一条扩容曲线上看，崩点有先后。并发从低到高，最先饱和的是调度器元数据与优先级队列（CPU 侧），表现为每步调度固定开销上升、组批延迟抖动；继续扩容，patch 聚合的通信半径扩大，跨节点组批时延逼近单步计算时延，异构收益被通信吃掉；再往上，显存激活池按档位叠加的占用逼近单卡容量，档位数被迫压缩，异构粒度变粗，收益收窄至 1.4 倍区间的下沿。功耗墙与尾延迟后处理则是机架级与业务级的软约束，先于硬崩点出现，表现为 SLO 达标率缓慢下滑而非吞吐骤降。</p>\n<p>工程判断是：扩容时应先解决调度器的元数据容量与查询效率（分片、索引、批量排序），再优化组批的节点局部性，最后才考虑压缩档位数。把顺序颠倒——先砍档位换显存——会让异构调度的空间粒度变粗，吞吐与画质同时受损，而 CPU 侧瓶颈依旧存在。规模上限的本质不是 GPU 算力上限，而是调度器每秒能处理多少 patch 元数据决策，以及拼接后处理能吞下多少边界修复算力。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-40\">四十 · 规模上去以后：元数据、拼接后处理与尾延迟先崩</h3>\n<p>这套方案的系统代价不在 DiT 前向本身，而在前向之外的两条链路：CPU 侧的 patch 元数据与优先级队列，以及解码期的拼接后处理。单请求时，切 patch、标预算、按分辨率聚 batch 只是几百条记录的簿记；当并发请求数上升，每条记录要携带坐标、目标分辨率、步数预算、SLO 截止时间与优先级，队列按 SLO 重排的复杂度随活跃 patch 数增长。调度器一旦成为 CPU 侧瓶颈，GPU 就会出现同质 batch 凑不满的空转——异构收益被簿记开销吃掉。可用下式判断何时越界：</p>\n<div class=\"formula\">$$\\text{Cost}=\\sum_{p}N_{p}\\,t_{\\text{step}}(r_{p}),\\quad \\text{Util}=\\frac{\\sum_{p}\\text{FLOPs}_{p}}{\\text{peak}\\cdot T_{\\text{wall}}}$$</div>\n<p>其中 $N_p$ 是 patch $p$ 的步数，$t_{\\text{step}}(r_p)$ 是该分辨率下单步时延。$r_p$ 越小，$t_{\\text{step}}$ 越低但 $N_p$ 与 patch 总数上升，调度与拼接开销按 patch 数线性膨胀；$r_p$ 越大则异构收益收窄，趋近于统一高分辨率的基线。规模上限因此由两个约束夹住：调度器元数据容量（活跃 patch 数 × 每 patch 记录）与拼接后处理算力（重叠区像素数 × 后处理算子）。</p>\n<p>拼接是第二处先崩的地方。patch 结果按坐标拼回完整 latent 再送 VAE 解码，接缝处需重叠与权重融合；重叠不足或权重设计不当会出现可见接缝与色带，而加大重叠直接抬高解码开销——重叠区像素在后处理里被重复计算，这部分算力不产生任何新内容。VAE 解码按 tile 并行可以摊薄单卡压力，但 tile 边界与 patch 边界不对齐时，接缝会从 latent 域迁移到像素域，后处理开销抵消吞吐收益。显存侧同样受牵连：patch 级 batch 需按分辨率对齐显存，混合分辨率组在同一 batch 内要按最高分辨率预留激活与 KV 类缓冲，低分辨率 patch 的显存被高分辨率邻居“借用”，实际占用高于其 FLOPs 应得的份额。</p>\n<p>尾延迟的失效条件最隐蔽。预算公式 $\\mathrm{budget}_p=\\mathrm{clip}\\big((\\mathrm{SLO}-t_{\\mathrm{wait}})/t_{\\mathrm{unit}}\\cdot c_p,\\,r_{\\min},r_{\\max}\\big)$ 依赖内容复杂度估计 $c_p$；估计偏差会让低复杂度 patch 预算过高、高复杂度 patch 预算过低，画质与 SLO 同时受损。高并发下 $t_{\\mathrm{wait}}$ 抖动，clip 下界 $r_{\\min}$ 被频繁触发，超时 patch 降级处理虽保住尾延迟，却让同一张图内出现分辨率不一致的区块，接缝概率上升。通信与功耗层面，patch 级调度把跨请求共享做成细粒度聚合，NVLink 上的激活搬运次数随 batch 重组频率上升；功耗则因 batch 尺寸频繁跳变而难以稳态调度。工程判断是：活跃 patch 数超过调度器可维护阈值、或拼接后处理算力占比逼近 DiT 前向时，应退回请求级分辨率分档，把异构粒度从 patch 抬到请求。</p>\n<h3 id=\"alg-mixed-resolution-serve-sec-41\">四十一 · 精度类失败：接缝、色带与预算失准</h3>\n<p>混合分辨率补丁调度最典型的精度失败不是数值溢出，而是<strong>空间不一致</strong>。同一个 latent 里，相邻 patch 走不同分辨率与不同步数，去噪轨迹在边界处不连续，拼回后表现为可见接缝、色带或局部纹理断层。根因有两层：其一，重叠区不足，patch 边界落在高频结构上（发丝、栅栏、文字边缘）时，两侧独立去噪无法收敛到同一解；其二，重叠区加权融合的权重设计不当，线性斜坡权重在低分辨率侧贡献过大，会把高分辨率侧的细节“抹平”。工程上把重叠宽度与 patch 尺寸绑定为固定比例，并让融合权重随两侧预算差单调变化——预算差越大，高预算侧权重越占优，避免低预算 patch 污染边界。</p>\n<p>第二类精度失败来自复杂度估计偏差。预算公式</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>里 $c_p$ 是唯一的主观量。若复杂度估计器把平滑天空判为高复杂度，低复杂度 patch 预算过高，白烧算力、拖累同批其他 patch；反之把密集纹理判为低复杂度，高复杂度 patch 预算过低，画质塌陷且 SLO 名义达标、实际返工。诊断手段是把 $c_p$ 与最终 patch 的实际步数、实际分辨率、以及拼接后局部梯度能量做成三联监控：若某 patch 的 $c_p$ 分位与实际梯度能量分位长期背离，说明估计器漂移，需要重校准而非调调度参数。</p>\n<p>代价侧要盯住后处理。重叠与融合不是免费的：重叠比例每提高一档，VAE 解码与融合的像素级工作量线性上升，解码开销可能吃掉 patch 异构带来的吞吐收益。判断标准是<strong>净收益</strong>——把融合后处理耗时计入 $\\text{Util}$ 的分母 $T_{\\text{wall}}$，若利用率提升被后处理抵消，说明重叠比例已越过拐点，应改用更小的重叠加更强的边界约束，而不是继续加宽重叠。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-42\">四十二 · 显存类失败：OOM 与批内分辨率错配</h3>\n<p>patch 级 batch 的显存占用不是按请求算的，而是按<strong>同质组内最大 patch 的分辨率</strong>算的。调度器按分辨率/步数聚合，一旦某个组混入了高于组内多数派的 patch，整组的激活与中间张量按最高档对齐，显存瞬间抬升，触发 OOM。这类失败在高并发下尤其隐蔽：单请求测试永远不复现，因为错配只在聚合时发生。</p>\n<p>诊断路径是给每个同质组记录三个量：组内分辨率直方图、组内步数直方图、组峰值显存。若峰值显存与组内最高分辨率强相关而与组大小弱相关，说明是分辨率对齐问题而非批量问题；此时应强制分组键包含分辨率档位，禁止跨档聚合，代价是组数变多、单组变小、GPU 填充率下降。反过来，若峰值显存随组大小线性上升，则是激活累积问题，需要限制单组 patch 数上限。</p>\n<p>OOM 的另一个来源是拼接后的完整 latent 与 VAE 解码并发。patch 结果按坐标拼回完整 latent 时，若拼接缓冲与解码 tile 同时驻留，显存峰值出现在“拼接完成、解码未启动”的窗口。工程做法是把拼接做成流式：按 tile 顺序拼接并立即送入解码，拼接缓冲只保留当前 tile 邻域，把峰值显存从“整图 + 整图解码”压到“tile + tile 邻域”。这与 VAE 分块解码的思路衔接，但此处要解决的是拼接与解码的<strong>时序重叠</strong>，不是解码本身的切块。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-43\">四十三 · 调度类失败：批抖动与路由不均</h3>\n<p>批抖动指同质组的组成在相邻调度周期之间剧烈变化，导致 GPU 上每步的有效工作量忽高忽低。根因是队列按 SLO 优先级重排时，高优先级请求不断插入，把已聚合的组打散重组。表现为：$\\text{Util}$ 的方差变大、单步时延的分布出现双峰、patch 元数据频繁失效重算。诊断指标是<strong>组重组率</strong>——单位时间内被拆散重建的组数占活跃组数的比例。重组率高时，优先级的抢占粒度太细，应把抢占从 patch 级上提到请求级，或给已入组的 patch 一个短时的不可抢占窗口。</p>\n<p>路由不均指 patch 在 GPU 之间分布倾斜。调度器按分辨率/步数聚合，若聚合键设计得过于粗糙，大量 patch 落到少数几个组，其余 GPU 空转。诊断看两个量：各 GPU 的活跃组数与组内 patch 数，以及跨 GPU 的组大小基尼系数。倾斜的典型原因是复杂度分档太少，低复杂度 patch 全部挤进同一个低预算组。解法是增加分档维度（分辨率 × 步数 × 复杂度桶），代价是元数据规模上升，与后文的调度器瓶颈直接相关。</p>\n<p>这两类失败的共同代价落在尾延迟上。批抖动使单步时延不可预测，SLO 余量被吃掉；路由不均使部分 GPU 排队深度远超均值，尾请求的 $t_{\\mathrm{wait}}$ 抬升，反过来压缩预算公式里的可用步数，形成“越堵越降级、越降级越不均”的正反馈。工程上必须给降级设一个下限 $r_{\\min}$，并在降级触发率超过阈值时告警——降级是保护尾延迟的手段，不是常态。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-44\">四十四 · 尾延迟尖刺：从排队到降级的链路诊断</h3>\n<p>尾延迟尖刺在混合分辨率服务里几乎总是多因叠加。把链路拆成四段分别计时：请求解析与切 patch、入队等待 $t_{\\mathrm{wait}}$、同质组聚合等待、DiT 前向与拼接解码。尖刺若集中在 $t_{\\mathrm{wait}}$，是队列深度问题；若集中在聚合等待，是组填充率不足、调度器在等凑批；若集中在前向，是组内分辨率错配导致的单步时延抬升；若集中在拼接解码，是后处理开销。</p>\n<p>分段计时的价值在于把“降级处理”从盲目动作变成定向动作。超时 patch 降级处理只应作用于前向段超时的 patch，对排队段超时的 patch 降级毫无意义——它还没开始算。诊断规则可以写成：若某 patch 的 $t_{\\mathrm{wait}}$ 已超过 $\\mathrm{SLO}$ 的固定比例，直接判超时并走降级分支，不再进入聚合；若前向段超时，则降低该 patch 的步数预算而非分辨率，因为分辨率变更会破坏已聚合组的同质性、引发组重组，反而放大抖动。</p>\n<p>尖刺的监控不能只看 P99 单值，要看 P99 的时间序列与降级触发率的联合走势。P99 抬升但降级率平稳，说明是容量问题；P99 抬升且降级率同步抬升，说明降级本身在制造尖刺——降级后的 patch 预算变小、组变小、填充率下降，单步有效工作量降低，$T_{\\text{wall}}$ 被拉长。此时正确动作是回滚降级阈值，而不是继续加压。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-45\">四十五 · 调度器瓶颈与元数据膨胀</h3>\n<p>patch 元数据与优先级队列在高并发下膨胀，调度器成为 CPU 侧瓶颈，这是本方法规模上限的直接来源。每个 patch 携带坐标、分辨率档、步数预算、复杂度估计、SLO 截止时间、所属请求 ID，元数据量与 patch 数成正比；patch 越小，元数据越多，调度开销越大，而异构收益随 patch 变小而上升——两条曲线交叉点就是最优 patch 尺寸。</p>\n<p>诊断调度器瓶颈看三个量：调度决策的 CPU 时间占端到端时延的比例、每周期处理的 patch 数、以及元数据内存占用。若 CPU 时间占比随并发上升而单调抬升且不收敛，说明调度器已饱和，此时增加 GPU 不会提升吞吐，只会加深队列。缓解手段按代价排序：先做元数据压缩（坐标与预算打包成定长结构、复杂度桶化），再做分组键的粗化（减少组数），最后才考虑降低 patch 粒度。反过来，若元数据内存占用是瓶颈而非 CPU 时间，说明队列积压，应优先处理背压而非优化数据结构。</p>\n<p>这里有一个与部署配方的直接冲突：量化可与 FP8/NVFP4 叠加以提升单卡算力，但量化不改变调度器的 CPU 开销。当调度器已是瓶颈时，叠加量化只会让 GPU 更快空转等调度，$\\text{Util}$ 不升反降。判断依据是 $\\text{Util}$ 的分子（有效 FLOPs）是否随量化档位提升而提升——若不提升，瓶颈在调度侧。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-46\">四十六 · 监控指标与回滚策略</h3>\n<p>监控要覆盖三层。精度层：接缝检测（拼接边界邻域的梯度能量与内部区域的比值）、色带检测（边界两侧的色度直方图偏移）、预算失准率（$c_p$ 分位与实际梯度能量分位的背离度）。显存层：组峰值显存、组内分辨率直方图的方差、拼接与解码的时序重叠窗口峰值。调度层：组重组率、跨 GPU 组大小基尼系数、$t_{\\mathrm{wait}}$ 分位、降级触发率、调度 CPU 时间占比。</p>\n<p>回滚要分级，且每级对应一个明确的触发条件，不能靠人肉判断。第一级回滚是<strong>参数级</strong>：重叠比例、复杂度分档数、降级阈值回到上一组稳定值，触发条件是接缝检测或降级触发率越限。第二级是<strong>策略级</strong>：关闭 patch 级异构，退回按请求统一分辨率，触发条件是调度 CPU 时间占比持续越限或组重组率持续越限——这一级会损失 1.4–1.8 倍的吞吐收益，但能把尾延迟拉回可预测区间。第三级是<strong>配置级</strong>：降低 patch 粒度或关闭量化叠加，触发条件是 OOM 频发且流式拼接无法压住峰值。</p>\n<p>回滚的关键工程判断是<strong>回滚粒度必须与故障域对齐</strong>。精度问题回滚重叠与融合参数即可，不必动调度；调度问题回滚分组键与抢占粒度，不必动精度参数；显存问题回滚分组对齐与拼接时序，不必动量化。把三类故障混在一个开关上，会导致一次回滚同时损失吞吐与画质，且无法归因。每一次回滚都应记录触发指标的快照，作为下一次容量规划与阈值设定的输入——混合分辨率服务的稳定性不是靠单点调参，而是靠故障域隔离与可回滚的分级策略维持的。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-47\">四十七 · 失效边界：从接缝、预算失准到调度器侧瓶颈</h3>\n<p>这套方案最先崩的地方往往不是 GPU，而是拼接。patch 结果按坐标拼回完整 latent 时，若重叠区宽度小于感受野或融合权重设计不当，接缝与色带会直接可见；后处理（重叠区加权、频域修补）本身要额外算力，<span class=\"formula\">$$\\mathrm{Cost}=\\sum_{p}N_{p}\\,t_{\\mathrm{step}}(r_{p})$$</span> 里的 <span class=\"formula\">$$t_{\\mathrm{step}}$$</span> 只算了 DiT 前向，没算这段解码期开销，于是吞吐收益被悄悄抵消。工程上应把重叠区宽度与 VAE tile 尺寸绑定，按 <span class=\"formula\">$$\\mathrm{Util}=\\frac{\\sum_{p}\\mathrm{FLOPs}_{p}}{\\mathrm{peak}\\cdot T_{\\mathrm{wall}}}$$</span> 反推：若 Util 提升但端到端延迟不降，先查拼接后处理占比。第二个失效点是预算失准：<span class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</span> 中 <span class=\"formula\">$$c_p$$</span> 是估计量，复杂度估计偏低会让高复杂度 patch 拿不到全预算，画质塌陷；估计偏高则低复杂度 patch 白烧算力，SLO 与画质双输。诊断手段是给每个 patch 记录实际步数与降级次数，按分辨率分桶统计预算命中率，偏差超阈值即回滚到保守的 <span class=\"formula\">$$r_{\\max}$$</span> 统一档。</p>\n<p>高并发下调度器自身会成为 CPU 侧瓶颈：patch 元数据（坐标、分辨率、步数、SLO 优先级、降级标记）随批大小线性膨胀，优先级队列重排的复杂度是 <span class=\"formula\">$$O(n\\log n)$$</span>，当 patch 数远大于请求数时，入队与重排的 CPU 时间可能超过同质 batch 的 GPU 前向时间。表现为批抖动——同质 batch 组大小忽大忽小、GPU 空转与排队交替出现。监控应采集三个量：同质组平均规模、组规模方差、调度器 CPU 占用的墙钟比例；方差上升而 GPU 利用率下降，就是元数据膨胀的信号。缓解靠限制单请求 patch 上限、把优先级重排降为分级桶（而非全排序），并把超时 patch 的降级决策前置到入队时而非运行中。</p>\n<p>路由不均与尾延迟尖刺同源：按分辨率聚 batch 意味着某一分辨率档的 patch 突然集中到达时，其他档的 batch 组被饿死，尾延迟尖刺出现在 SLO 最紧的那一档。监控要按分辨率档分别看 P99 而非全局均值，并对每档设独立的等待时间水位；一旦某档 <span class=\"formula\">$$t_{\\mathrm{wait}}$$</span> 逼近 SLO，立即触发该档 patch 的降级（降分辨率或减步），而不是等全局队列报警。回滚策略分三级：预算层回滚（把 <span class=\"formula\">$$c_p$$</span> 估计切换为固定值）、调度层回滚（关闭 patch 级异构，退回请求级同质 batch）、拼接层回滚（增大重叠区、关闭 tile 并行解码）。三级回滚都应能在不重启服务的前提下按开关切换，因为失效往往只在特定混合负载配方下出现，全量回退会丢掉 1.4–1.8 倍的吞吐收益。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>观测指标</th><th>回滚动作</th></tr></thead><tbody><tr><td>可见接缝/色带</td><td>重叠不足或融合权重</td><td>解码后处理耗时占比</td><td>增大重叠区、关 tile 并行</td></tr><tr><td>画质塌陷但延迟正常</td><td>复杂度估计偏低</td><td>各分辨率档预算命中率</td><td>预算层回滚至固定 <span class=\"formula\">$$c_p$$</span></td></tr><tr><td>批抖动、GPU 空转</td><td>元数据膨胀</td><td>组规模方差、调度器 CPU 占比</td><td>调度层回滚至请求级 batch</td></tr><tr><td>单档 P99 尖刺</td><td>路由不均</td><td>分档等待水位</td><td>该档 patch 前置降级</td></tr></tbody></table>\n<h3 id=\"alg-mixed-resolution-serve-sec-48\">四十八 · 决策表的坐标轴：先问三个问题</h3>\n<p>把本方法放进同族算法的选择空间里，决策不是按“哪个更先进”排序，而是按三个可判定的问题排序：异构性出现在请求之间还是请求之内；预算分配发生在去噪前还是去噪后；调度粒度是阶段、块还是 patch。混合分辨率补丁调度的坐标是“请求内 × 去噪前 × patch”，这三个坐标一旦确定，同族里其余算法的适用条件就自然被排除掉一部分。第一个问题决定收益上限：若线上流量里高分辨率请求占比极高、且内容复杂度分布集中，patch 级异构能榨出的算力差很小，收益会向 1.0 倍收敛；只有当高低分辨率混跑且复杂度差异显著时，才可能触及 1.4–1.8 倍这一区间。第二个问题决定工程代价落在哪一侧：去噪前分配预算意味着调度器必须持有 patch 元数据、优先级与坐标映射，CPU 侧成本与拼接后处理成本同时上身；去噪后（缓存、跳步类）则把代价转移到一致性校验与命中率上。第三个问题决定失败模式：粒度越细，接缝与元数据膨胀越突出；粒度越粗，异构收益越窄。</p>\n<p>把这三问写成判定式，便于在容量规划会上直接过一遍：设请求集合中分辨率方差为 $\\sigma_r^2$、复杂度方差为 $\\sigma_c^2$、SLO 分级数为 $K$，则本方法的期望收益大致随 $\\sigma_r^2\\cdot\\sigma_c^2\\cdot K$ 单调，而代价随 patch 数 $N_p$ 与拼接重叠率 $\\rho$ 单调。工程判断可以简化为：当 $\\sigma_r^2$ 与 $\\sigma_c^2$ 同时偏小，或 $N_p$ 已大到调度器元数据成为瓶颈时，不要选本方法，改走阶段级流水或块级跳步。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-49\">四十九 · 与阶段级流水的对照：切分维度不同，代价位置不同</h3>\n<p>阶段级扩散服务流水按管线阶段切分（编码、去噪、VAE 解码），其调度单位是阶段而非空间区域，异构性来自不同请求处在不同阶段，靠流水填充提高整卡占用。它不需要 patch 元数据，也不需要拼接后处理，因此 CPU 侧开销低、接缝问题不存在；但它对“同一请求内部画质分级”无能为力——一个请求要么全预算要么全降级，无法让画面中心高预算、边角低预算。本方法则相反：它把异构性下沉到请求内部的空间维度，代价是调度器必须维护坐标与优先级，且 VAE 解码要按 tile 并行以消化拼接开销。选择判据是：若业务需要按区域或按内容复杂度分级画质（例如主体区域必须清晰、背景可降级），选本方法；若业务只需要按请求整体分级 SLO、且请求形态相对同质，选阶段级流水，因为它的显存与带宽代价更可预测，调度器不会成为 CPU 侧瓶颈。</p>\n<p>两者可以叠加但不应互相替代：阶段级流水决定“哪个请求先进入去噪”，patch 调度决定“进入去噪后每个区域花多少预算”。叠加时要注意显存对齐——patch 级 batch 需按分辨率对齐显存，否则同质 batch 的聚合会被显存碎片打断，反而拉低 $\\text{Util}$。系统代价上，阶段级流水的尾延迟主要由最长阶段的排队决定，而本方法的尾延迟由超时 patch 的降级策略兜底，两者对 SLO 的作用点不同。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-50\">五十 · 与 VAE 分块、块级跳步、特征缓存的对照</h3>\n<p>VAE 分块并行解码只在解码期切块，去噪阶段仍是整图统一预算，因此它解决的是解码显存峰值与并行度，不解决去噪算力在请求间的错配；它的接缝风险集中在解码 tile 边界，而本方法的接缝风险集中在 latent 拼接处，需要重叠与后处理，二者后处理算力不能互相抵扣。块级跳步与特征缓存工作在去噪后或跨步维度，靠复用中间结果省算力，收益取决于命中率与一致性容忍度，其失败模式是画质漂移而非接缝；本方法的失败模式是复杂度估计偏差导致预算失准，两者诊断手段不同——前者看缓存命中与步间误差，后者看 patch 预算与实际复杂度的偏差分布。</p>\n<p>与 DiT 分块 PTQ 校准、MX 混合精度分块、FP8 注意力与 GEMM 这类数值精度条目相比，本方法不改数值格式，而是改“每个 patch 走多少步、多大分辨率”，因此它可以与 FP8/NVFP4 量化叠加：量化压低单步时延 $t_{\\text{unit}}$，patch 调度放大异构收益，二者相乘而非相加。代价叠加时要注意，量化误差在低预算 patch 上更容易被放大，因为低分辨率或少步本身已损失细节，再叠低精度会加剧色带，这正是接缝与色带失败模式在混合配置下的高发场景。</p>\n<table class=\"mini\"><thead><tr><th>同族算法</th><th>异构维度</th><th>分配时点</th><th>主要代价</th><th>适用条件</th></tr></thead><tbody><tr><td>混合分辨率补丁调度</td><td>请求内空间</td><td>去噪前</td><td>拼接后处理、调度器元数据</td><td>高低分辨率混跑、复杂度差异大、需区域分级画质</td></tr><tr><td>阶段级扩散服务流水</td><td>请求间阶段</td><td>管线级</td><td>阶段排队、显存驻留</td><td>请求形态同质、按请求整体分级 SLO</td></tr><tr><td>VAE 分块并行解码</td><td>解码 tile</td><td>解码期</td><td>tile 边界接缝、并行同步</td><td>解码显存受限、去噪预算无需分级</td></tr><tr><td>块级跳步/特征缓存</td><td>跨步复用</td><td>去噪后</td><td>命中率、画质漂移</td><td>相邻步高度相似、可容忍一致性偏差</td></tr><tr><td>DiT 分块 PTQ / MX 分块</td><td>数值精度</td><td>权重/激活级</td><td>校准成本、低预算下误差放大</td><td>需压单步时延、可与 patch 调度叠加</td></tr></tbody></table>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-51\">五十一 · 预算公式在两族之间的取舍</h3>\n<p>本方法的核心分配式是 $$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$ 它与阶段级流水的差别在于：阶段级流水把 $\\mathrm{SLO}-t_{\\mathrm{wait}}$ 整段留给一个请求，而这里把它按 $c_p$ 拆到 patch 上。拆分的收益来自 $\\sum_p \\mathrm{FLOPs}_p$ 的下降，代价来自 $\\mathrm{clip}$ 上下界之外的 patch 无法再压缩——当 $t_{\\mathrm{wait}}$ 接近 SLO 时，大量 patch 被压到 $r_{\\min}$，画质整体塌陷，此时正确动作是队列按 SLO 优先级重排并让超时 patch 降级，而不是继续压预算。工程上应监控被 $\\mathrm{clip}$ 截断的 patch 比例，该比例持续偏高说明调度器容量或硬件档位不足，需要按显存选卡或增加副本，而非调参。</p>\n<p>与块级跳步对照，跳步相当于把 $c_p$ 恒定为 0 的一类极端预算分配，收益确定但画质不可分级；本方法保留 $c_p$ 的空间变化，因此能把预算花在主体区域。与 VAE 分块对照，解码 tile 的并行度决定拼接后处理算力能否被吸收，若 VAE 解码未按 tile 并行，拼接与重叠后处理会直接吃掉吞吐收益，使实测倍数落在 1.4 倍下沿甚至更低。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-52\">五十二 · 适用条件与规模上限的判定</h3>\n<p>适用条件可以收敛为四条同时成立：流量中高低分辨率请求混跑且占比均不可忽略；内容复杂度在请求内空间分布不均；业务接受按区域分级画质并愿意承担拼接后处理；调度器所在 CPU 侧有余量承载 patch 元数据与优先级队列。四条中任一不成立，就应转向表中相邻算法。规模上限由两个约束夹住：patch 过小则 $N_p$ 增大，调度与拼接开销上升，元数据在高并发下膨胀成为 CPU 侧瓶颈；patch 过大则同质 batch 内分辨率差异收窄，异构收益向 1.0 倍回落。部署时按显存选卡、量化与 FP8/NVFP4 叠加、VAE 按 tile 并行，这三项是把 1.4–1.8 倍落到实测的必要条件，缺一项都会让收益被后处理或调度开销抵消。</p>\n<p>最后落在工程判断上：选型会上不要问“本方法是否更强”，而要问“我的流量方差是否足以支付 patch 元数据与拼接后处理的固定成本”。若支付得起且需要区域级画质分级，本方法是同族中唯一在去噪前做请求内空间异构的选项；若支付不起，阶段级流水加块级跳步的组合在显存与 CPU 侧都更可控，代价是放弃请求内的预算精细化。</p>\n\n<h3 id=\"alg-mixed-resolution-serve-sec-53\">五十三 · 边界与选型：什么时候该用 patch 级异构，什么时候退回同质批</h3>\n<p>本方法在去噪前就按 patch 分配异构预算，属请求内空间异构调度，这一点决定了它和两个近邻的分工。阶段级流水按管线阶段切分（编码、去噪、解码各占不同资源），解决的是阶段间资源错配，请求内部仍是同分辨率同预算；VAE 分块只在解码期切 tile，去噪阶段依旧整图统一分配，因此对“高分辨率请求拖慢低分辨率请求”这个原始病灶无效。三者可叠加而非互斥：阶段级流水管跨阶段，VAE 分块管解码显存峰值，patch 级异构管去噪期的算力分配。选型的第一个判据是负载的<b>分辨率方差</b>——若请求分辨率几乎一致，patch 级调度只增加元数据开销而无异构收益，应退回同质连续批处理；第二个判据是<b>内容复杂度方差</b>，若同一张图内平坦区域与高频纹理差异不大，按复杂度分配预算的收益也随之收窄。</p>\n<p>预算分配的核心是下面这条裁剪式，它把 SLO 剩余时间、排队等待与内容复杂度耦合到一个 patch 的分辨率/步数上：</p>\n<div class=\"formula\">$$\\mathrm{budget}_p=\\mathrm{clip}\\left(\\frac{\\mathrm{SLO}-t_{\\mathrm{wait}}}{t_{\\mathrm{unit}}}\\cdot c_p,\\, r_{\\min},\\, r_{\\max}\\right)$$</div>\n<p>公式暴露了两个失效条件。其一，$t_{\\mathrm{wait}}$ 在队列按 SLO 优先级重排时会持续变化，若调度器用入队时刻的快照计算预算，高并发下预算会系统性偏高，尾延迟反而恶化；应以出队时刻重算并允许超时 patch 降级。其二，$c_p$ 是估计量，复杂度估计偏差直接导致低复杂度 patch 预算过高或高复杂度 patch 预算过低，画质与 SLO 同时受损——这是本方案最脆弱的环节，工程上应保留一条“估计置信度低则给全预算”的保守分支，把风险转成吞吐损失而非画质事故。</p>\n<p>系统代价集中在三处，且都随 patch 变小而放大。调度侧：patch 元数据与优先级队列在高并发下膨胀，CPU 侧调度器成为瓶颈，规模上限受元数据容量约束；拼接侧：patch 拼接处重叠不足或权重设计不当会出现可见接缝与色带，重叠与后处理增加 VAE 解码开销，后处理开销足以抵消吞吐收益；显存侧：同质 patch 组需按分辨率对齐显存，组内最大分辨率决定该 batch 的激活占用，patch 过小则组数增多、对齐浪费上升，patch 过大则异构收益收窄。因此 patch 尺寸存在一个由调度开销与异构收益共同夹出的窗口，而不是越小越好。</p>\n<table class=\"mini\"><thead><tr><th>相邻方案</th><th>切分维度</th><th>解决什么</th><th>不解决什么</th><th>适用条件</th></tr></thead><tbody><tr><td>patch 级异构调度</td><td>请求内空间 + 预算</td><td>混合分辨率下的算力错配、尾延迟分级</td><td>阶段间资源错配、解码显存峰值</td><td>分辨率与复杂度方差大、SLO 分级明确</td></tr><tr><td>阶段级流水</td><td>管线阶段</td><td>编码/去噪/解码资源配比</td><td>请求内分辨率不均</td><td>阶段耗时差异显著、多请求并发</td></tr><tr><td>VAE 分块</td><td>解码期 tile</td><td>高分辨率解码显存峰值</td><td>去噪期统一预算</td><td>解码是显存与延迟主瓶颈</td></tr></tbody></table>\n<p>决策落到工程判断上：先测分辨率方差与复杂度方差，两者都小则同质批加阶段级流水即可；分辨率方差大而复杂度方差小，用按分辨率分组的同质批、不做 patch 内异构；两者都大才启用 patch 级调度，并把 $r_{\\min}$ 抬高以限制最小 patch，避免调度与拼接开销吃掉 1.4–1.8 倍的吞吐收益。量化可与 FP8/NVFP4 叠加，但 patch 级 batch 的显存对齐要在量化后重新标定，否则组内激活占用估算失准会让对齐浪费重新抬头。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 少步采样与一致性蒸馏</td></tr><tr><td>解决什么</td><td>高分辨率请求与低分辨率请求混跑时，统一按最高分辨率分配显存与算力，导致低分辨率请求被拖慢、GPU 利用率与 SLO 双…</td></tr><tr><td>一句话机制</td><td>把图像切成 patch，按内容复杂度与请求 SLO 分配不同分辨率与步数预算，patch 级调度器把同分辨率 patc…</td></tr><tr><td>代价与失效</td><td>patch 拼接处易出现接缝，需重叠与后处理，增加解码开销；调度器需维护 patch 元数据与优先级，工程复杂度高</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-mixed-resolution-serve · 共 8 个片段</p>\n";break;}}})();
